insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('si-d-schleifn-geebm', 'si d''Schleifn geebm', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich die Schleife geben', '[{"kategorie": "wörtlich", "text": "\"sich die Kranzschleife umhängen\""}, {"kategorie": "allg.", "text": "sich das Leben nehmen, Selbstmord begehen, den Freitod wählen, [[si ins Pendl haun]], [[si zwaa Määta tiafa bringan]], [[si ins Hangal schmeissn]], [[in Tood de Goowä mochn]], [[si s''Rippal geebm]], [[si de Kuugl geebm]], [[si haamdraan]], [[si in Liachthof haun]]"}]'::jsonb, 'Gibsd da sööwa de Schleifn oda sois I da umhängan? - Suachs da aus!'),
  ('gibsd-da-soeoewa-de-schleifn-oda-sois-i-da-umhaengan-suachs-da-aus', 'Gibsd da sööwa de Schleifn oda sois I da umhängan? - Suachs da aus!', '', '', '', 'Wiener Gaunersprache', 'Gibst du dir selber die Schleife oder soll ich sie dir umhängen? - Such''s dir aus!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Gibst du dir selber die Kranzschleife oder soll ich sie dir umhängen? - Such''s dir aus!\"  2. Nimmst du dir selbst das Leben oder soll ich das für dich erledigen? - Such''s dir aus!  3. Wählst du den Freitod oder soll ich dich ins Jenseits katapultieren? - Sag mir, was dir lieber ist!"}]'::jsonb, 'si d''Schleifn geebm'),
  ('si-zwaa-meta-tiafa-bringan', 'si zwaa Meta tiafa bringan', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich zwei Meter tiefer bringen', '[{"kategorie": "wörtlich", "text": "\"sich zwei Meter tiefer unter die Erde bringen\""}, {"kategorie": "", "text": "\"sich ins Grab bringen\""}, {"kategorie": "", "text": "\"sich das Leben nehmen\""}, {"kategorie": "", "text": "\"Selbstmord begehen\""}]'::jsonb, ''),
  ('da-schaani-hod-si-zwaa-maeaeta-tiafa-brochd-mid-da-eiganan-dienstpuffn', 'Da Schaani hod si zwaa Määta tiafa brochd - mid da eiganan Dienstpuffn!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Schani hat sich zwei Meter tiefer gebracht - mit der eigenen Dienstpuffen!', '[{"kategorie": "wörtlich", "text": "\"Der Schani hat sich selbst aus dem Verkehr gezogen - mit der eigenen Dienstwaffe!\"  2. \"Der Johann hat sich eigenhändig ins Jenseits befördert - mit der eigenen Dienstwaffe!\"  3. \"Der Schani hat Selbstmord begangen - mit der eigenen Dienstwaffe!\""}]'::jsonb, ''),
  ('da-weana-daschiassd-si-heechstns-mit-ana-leewawuaschd', 'Da Weana daschiassd si heechstns mit ana Leewawuaschd!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Wiener erschießt sich höchstens mit einer Leberwurst', '[{"kategorie": "wörtlich", "text": "\"Der Wiener verabschiedet sich von dieser Welt eher mit einer Leberwurst denn mit einer Kugel im Mund!\"  2. \"Ein echter Wiener gibt sich lieber die Leberwurst statt der Kugel!\"  3. \"Der Wiener schießt sich höchstens eine Leberwurst rein, aber sicher keine Kugel!\""}]'::jsonb, ''),
  ('des-is-ma-leewawuaschd', 'Des is ma leewawuaschd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist mir Leberwurst!', '[{"kategorie": "wörtlich, scherzhaft für", "text": "\"Das ist mir sowas von egal!\"  2. Das geht mir [[am]] Arsch vorbei!  3. [[Des]] is ma [[blunzn]]!  4. [[Des]] is ma powidl!"}]'::jsonb, ''),
  ('mei-klaane-mochd-schoo-luluu-ins-topfal', 'Mei Klaane mochd schoo Luluu ins Topfal!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Meine Kleine macht schon Lulu ins Topferl!', '[{"kategorie": "wörtlich", "text": "\"Meine Tochter macht schon Pipi ins Töpfchen!\"  2. Meine Maus geht schon aufs Töpfchen für ihr Lulu!  3. Unsere Prinzessin kann ihr Lulu jetzt schon ganz alleine ins Topferl machen!"}]'::jsonb, 'Luluu mochn'),
  ('dea-hod-si-sei-luluu-im-reissvaschluss-vom-hoosntial-eizwickd-des-woas-daunn-mit-da-famuelienplanung', 'Dea hod si sei Luluu im Reissvaschluss vom Hoosntial eizwickd - des woas daunn mit da Famülienplanung!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der hat sich sein Lulu im Reißverschluss vom Hosentürl eingezwickt - das war''s dann mit der Familienplanung!', '[{"kategorie": "wörtlich", "text": "\"Der hat sich sein bestes Stück im Zippverschluss vom Hosenschlitz eingeklemmt - das bedeutet das Ende seiner Fruchtbarkeit!\"  2. Seit dem Zwick-Unfall ist sein Lulu nur noch Deko – einmal falsch gezippt, und der Lümmel hat sich vom Dienst abgemeldet!  3. Sein Zumpferl hat sich im Hosentürl verheddert – jetzt ist sein Stammbaum hin!"}]'::jsonb, ''),
  ('regian-is-nix-fia-luluus', 'Regian is nix fia Luluus!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Regieren ist nichts für Lulus!', '[{"kategorie": "wörtlich", "text": "\"Regieren ist nichts für Warmduscher!\" (legendärer Ausspruch der Wiener Grün-Politikerin Maria Vassilakou)"}, {"kategorie": "", "text": "\"Regieren ist nichts für Weicheier!\"  3. \"Regieren ist nichts für Schisser!\""}]'::jsonb, ''),
  ('pipii-mochn-zeend-putzn-und-daunn-ob-ind-harpfn', 'Pipii mochn, Zeend putzn und daunn ob ind Harpfn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Pipi machen, Zähne putzen und dann ab in die Harpfen!', '[{"kategorie": "wörtlich", "text": "\"Pipi machen, Zähne putzen und dann ab ins Bett!\"  2. Noch schnell aufs Töpfchen, Zähnchen schrubben – und dann ab ins Bettchen!  3. (Reim): Noch schnell ins Bad, und dann ins Bett – so endet jeder Tag ganz nett!"}]'::jsonb, 'Pipii mochn'),
  ('den-sei-pipii-is-klaana-ois-des-von-mein-sechsjaeaerichn-buam', 'Den sei Pipii is klaana ois des von mein sechsjäärichn Buam!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Das Pipi von ihm ist kleiner als das von meinem sechsjährigen Buben!', '[{"kategorie": "wörtlich", "text": "\"Sein Schniedel ist kleiner als der von meinem Sechsjährigen!\"  2. Wenn’s nach seinem Zumpferl geht, gehört er in die Windelgruppe!  3. Was der da unten hat, sieht kleiner aus als das Pimmelchen von meinem Sechsjährigen!"}]'::jsonb, ''),
  ('des-is-jo-pipii-geeng-des-wos-no-kummd', 'Des is jo Pipii geeng des wos no kummd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist ja Pipi gegen das, was noch kommt!', '[{"kategorie": "wörtlich", "text": "\"Das ist ja Pipifax gegen das, was noch kommt!\"  2. \"Das ist ja Kinderkram - verglichen mit dem, was noch auf uns zukommt!\"  3. \"Das ist ja nur ein kleiner Vorgeschmack – der echte Wahnsinn kommt erst noch!\""}]'::jsonb, ''),
  ('mei-klaane-mochd-schoo-lulli-ins-topfal', 'Mei Klaane mochd schoo Lulli ins Topfal!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Meine Kleine macht schon Lulli ins Topferl!', '[{"kategorie": "wörtlich", "text": "\"Meine Tochter macht schon Pipi ins Töpfchen!\"  2. Meine Maus geht schon aufs Töpfchen für ihr Lulu!  3. Unsere Prinzessin kann ihr Lulli jetzt schon ganz alleine ins Topferl machen!"}]'::jsonb, 'Lulli mochn'),
  ('dea-is-st-schdoiz-auf-sei-lulli-dabei-siichsdas-ned-amoi-mid-an-haundschbiagl', 'Dea is st schdoiz auf sei Lulli - dabei siichsdas ned amoi mid an Haundschbiagl!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der ist so stolz auf sein Lulli - dabei siehst du es nicht einmal mit einem Handspiegel!', '[{"kategorie": "wörtlich", "text": "\"Der ist so stolz auf sein bestes Stück - dabei siehst du es nicht einmal mit einem Handspiegel!\"  2. Der prahlt mit seinem Zipfel – dabei hängt da weniger als an einem Teebeutel!  3. Der ist so stolz auf sein Zumpferl – dabei musst du danach suchen wie nach Atlantis!"}]'::jsonb, ''),
  ('oone-sei-lulli-schloofd-da-bua-ned-ei', 'Oone sei Lulli schloofd da Bua ned ei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ohne sein Lulli schläft der Bun nicht ein!', '[{"kategorie": "wörtlich", "text": "\"Ohne seinen Schnuller schläft der Bub nicht ein!\"  2. Der Luller muss in den Mund – sonst schäft der Bub nicht ein!  3. Der Bub braucht seinen Schnuller zum Einschlafen – sonst wird’s nichts!"}]'::jsonb, ''),
  ('mit-lauta-lullis-in-da-maunnschofd-gwinnsd-ka-maetsch', 'Mit lauta Lullis in da Maunnschofd gwinnsd ka Mätsch!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Mit lauter Lullis in der Mannschaft gewinnst du kein Match!', '[{"kategorie": "wörtlich", "text": "\"Mit so einer Truppe aus Warmduschern gewinnst du kein Match!\"  2. \"Mit lauter Weicheiern im Team fährt man keine Punkte ein!\"  3. \"Mit einer Elf ohne Eier holst du in der Liga nichts!\""}]'::jsonb, ''),
  ('lulli-mochn', 'Lulli mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'Lulli machen', '[{"kategorie": "wörtlich", "text": "[[Pipi machen]]"}, {"kategorie": "Kindersprache", "text": "[[wiwi machen]]"}, {"kategorie": "", "text": "Wasser lassen, urinieren, [[pinkeln]], [[pieseln]], [[pischen]], [[brunzen]], [[schiffen]], [[in Kaschbal schneizn]]"}]'::jsonb, ''),
  ('auf-da-grueuenan-wiisn-sitzd-a-krokodueue-des-weedld-mitn-schwanzal-und-waass-ned-wos-es-wueue', 'Auf da grüünan Wiisn sitzd a Krokodüü - des weedld mitn Schwanzal und waass ned, wos es wüü!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Auf der grünen Wiese sitzt ein Krokodil - das wedelt mit dem Schwänzchen und weiß nicht was es will!', '[{"kategorie": "wörtlich, Text eines Volkslieds", "text": "\"Auf der grünen Wiese sitzt ein Krokodil – es grinst ganz breit und hat kein Ziel!\"  2. Auf der grünen Wiese sitzt ein Krokodil – es schaut in alle Richtungen und weiß nicht, was es will!  3. Auf der grünen Wiese sitzt ein Krokodil – das wedelt mit dem Schwänzchen und chillt, so viel es will!"}]'::jsonb, ''),
  ('ea-soogd-sei-schwanzal-is-a-heagoodsgschenk-i-daed-eeha-sonng-a-mueuede-schbende', 'Ea soogd, sei Schwanzal is a Heagoodsgschenk - I däd eeha sonng: a müüde Schbende!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er sagt, sein Schwanzerl ist ein Herrgottsgeschenk - ich tät eher sagen: ''ne milde Spende!', '[{"kategorie": "wörtlich", "text": "\"Er sagt, sein Schwanzi sei ein Geschenk Gottes – ich würd'' eher sagen: ''ne milde Spende!\"  2. \"Er nennt sein Zumpferl ''ein Geschenk Gottes'' - ich würd eher sagen: ein Rohrkrepierer!\"  3. Er prahlt mit seiner \"Monstranz\" –  dabei ist sein Schwänzchen eher eine Wasserpsitole!"}]'::jsonb, ''),
  ('si-hod-im-schdee-pischd-reschpekt', 'Si hod im Schdee pischd - Reschpekt!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie hat im Stehen gepischt - Respekt!', '[{"kategorie": "wörtlich", "text": "\"Sie hat im Stehen gepinkelt - alle Achtung!\"  2. \"Sie hat im Stehen ihr Geschäft gemacht – Hut ab!\"  3. \"Sie pinkelt wie ein Kerl – und das ohne nasse Schuhe. Respekt!\""}]'::jsonb, ''),
  ('heit-pischds-uandlich-owa-do-hueuefd-ka-schiam-mea-do-brauchsd-a-boot', 'Heit pischds uandlich owa - do hüüfd ka Schiam mea, do brauchsd a Boot!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Heute pischt es ordentlich herunter - da hilft kein Schirm mehr, da brauchst ein Boot!', '[{"kategorie": "wörtlich", "text": "\"Heute schüttet''s wie aus Kübeln - da hilft kein Schirm mehr, da brauchst ein Boot!\"  2. Was da vom Himmel heute runterprasselt, ist keine Dusche – das ist eine Sintflut!  3. Heute waschelt es vom Himmel runter, als gäb''s kein Morgen!"}]'::jsonb, ''),
  ('i-pinkl-a-jeeds-moi-aum-soeoebm-baam-revia-is-revia', 'I pinkl a jeeds Moi aum sööbm Baam - Revia is Revia!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich pinkel'' ein jedes Mal an denselben Baum – Revier ist Revier!', '[{"kategorie": "wörtlich", "text": "\"Ich brunze jedes Mal an denselben Baum – Revier bleibt Revier!\"  2. Ich piesel jedes Mal an denselben Baum – Revier muss man pflegen!  3. Ich pische immer an denselben Baum - Revier muss schließlich verteidigt werden!"}]'::jsonb, ''),
  ('pissn-tuan-nua-de-preissn-bei-uns-geed-ma-in-kaschbal-schneizn', 'Pissn tuan nua de Preissn - bei uns geed ma in Kaschbal schneizn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Pissen tun nur die Preußen - bei uns geht man den Kasperl schnäuzen!', '[{"kategorie": "wörtlich", "text": "\"Pissen tun nur die Deutschen - wir Wiener gehen den Kasperl schnäuzen!\"  2. In Piefkenesien geht man pissen - in der Hauptstadt der Musik schnäuzt man den Kasperl!  3. Piefkes pissen - Wiener schnäuzen ihren Kasperl!"}]'::jsonb, ''),
  ('pipii-mochn', 'Pipii mochn', '', '', '', 'Grundwortschatz Wienerisch', 'Pipi machen', '[{"kategorie": "wörtlich", "text": "[[Pipi machen]] (lautmalerisches Lallwort, welches das Geräusch des Urinierens nachahmt)"}, {"kategorie": "Kindersprache für", "text": "Wasser lassen, urinieren, [[wiwi]] machen, [[Luluu]] mochn, [[pinkln]], [[pischn]], [[piisln]] [[brunzn]], [[schiffn]], [[in]] Kaschbal schneizn"}]'::jsonb, ''),
  ('luluu-mochn', 'Luluu mochn', '', '', '', 'Grundwortschatz Wienerisch', 'Lulu machen', '[{"kategorie": "wörtlich", "text": "[[Lulu machen]] (lautmalerisches Lallwort, welches das Geräusch des Urinierens nachahmt)"}, {"kategorie": "Kindersprache für", "text": "Wasser lassen, urinieren, [[wiwi machen]],  [[pinkln]], [[pischn]], [[brunzn]], [[schiffn]], [[piisln]], [[in]] Kaschbal schneizn"}]'::jsonb, 'I moch Luluu ind Hoosn vua lauta Lochn!'),
  ('i-moch-luluu-ind-hoosn-vua-lauta-lochn', 'I moch Luluu ind Hoosn vua lauta Lochn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich mach'' Lulu in die Hose vor lauter Lachen!', '[{"kategorie": "wörtlich", "text": "\"Ich mach mir vor lauter Lachen in die Hose!\"  2. Ich mach gleich Pipi vor lauter Lachen!  3. Ich krieg ''nen derartigen Lachkrampf, dass die Dichtungen gleich nachgeben!"}]'::jsonb, ''),
  ('da-baumpaletsch-muass-luluu', 'Da Baumpaletsch muass luluu!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Bamperletsch muss lulu', '[{"kategorie": "wörtlich", "text": "\"Das Kindchen muss Pipi machen!\"  2. \"Das Kind muss aufs Töpfchen!\"  3. \"Das Kind muss Wasser lassen!\""}]'::jsonb, ''),
  ('dea-laechld-scheissfreindlich-und-beschdoeoed-da-hintarucks-schoo-dein-groobschdaa', 'Dea lächld scheissfreindlich und beschdööd da hintarucks schoo dein Groobschdaa!', '', '', '', 'Wiener Gaunersprache', 'Der lächelt scheißfreundlich und bestellt dir hinterrücks schon deinen Grabstein!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Der grinst wie ein Engel und bestellt dir hinterrücks schon deinen Sarg!\"  2. Der ist Zucker vorn und Zement hintenrum!  3. Der lächelt dir scheißfreundlich ins Gesicht – und schickt dich gleichzeitig auf die letzte Reise!"}]'::jsonb, ''),
  ('drei-doktoatiitl-nui-menschnvaschdaund-a-klassischa-fochtrottl', 'Drei Doktoatiitl, nui Menschnvaschdaund - a klassischa Fochtrottl!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Drei Doktortitel, null Menschenverstand – ein klassischer Fachtrottel!', '[{"kategorie": "wörtlich", "text": "\"Drei Doktortitel und zu doof zum Leben – ein Fachidiot in Reinform!\"  2. Mehr akademische Titel als gesunder Menschenverstand – das Paradebeispiel eines Nerds!  3. Drei Titel vor dem Namen, aber nicht in der Lage, einen Nagel in die Wand zu schlagen – ein Fachtrottel im Maßanzug!"}]'::jsonb, ''),
  ('des-is-a-gschdudiiata-dea-schaut-uns-klaane-leid-ned-amoi-au', 'Des is a Gschdudiiata, dea schaut uns klaane Leid ned amoi au!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist ein Gstudierter! Der schaut uns kleine Leute nicht einmal an!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Studierter - der redet nur mit seinesgleichen!\"  2. Dieser Mehrfachakademiker hält sich für weiß Gott wen - für den sind wir nicht einmal einen Blick wert!  3. Der hat studiert – für den sind wir nur das Fußvolk!"}]'::jsonb, ''),
  ('des-is-a-gschdudiiata-dem-brauchsd-nix-dazoeoen-dea-waass-wias-rennd', 'Des is a Gschdudiiata, dem brauchsd nix dazöön - dea waass, wias rennd!', '', '', '', 'Wiener Gaunersprache', 'Das ist ein Gstudierter, dem brauchst du nichts zu erzählen - der weiß, wie''s rennt!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Ex-Knacki, dem brauchst du nichts zu erzählen - der weiß, wie der Hase läuft!\"  2. Das ist ein Häfenbruder, der hat seine Runden gedreht – den musst du nicht briefen, der kennt das Spiel!  3. Das ist ein Mehrfachvorbestrafter, der hat mehr Knasterfahrung als wir alle zusammen – also red nicht mit dem wie mit ''nem Zivi [=Zivildienstleistender]!"}]'::jsonb, ''),
  ('des-is-a-schdudiiata-dea-schaut-uns-klaane-leid-ned-amoi-au', 'Des is a Schdudiiata, dea schaut uns klaane Leid ned amoi au!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist ein Studierter! Der schaut uns kleine Leute nicht einmal an!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Studierter - der redet nur mit seinesgleichen!\"  2. Dieser Mehrfachakademiker hält sich für weiß Gott wen - für den sind wir nicht einmal einen Blick wert!  3. Der hat studiert – für den sind wir nur das Fußvolk!"}]'::jsonb, ''),
  ('des-is-a-schdudiiata-dem-brauchsd-nix-dazoeoen-dea-waass-wias-rennd', 'Des is a Schdudiiata, dem brauchsd nix dazöön - dea waass, wias rennd!', '', '', '', 'Wiener Gaunersprache', 'Das ist ein Studierter, dem brauchst du nichts zu erzählen - der weiß, wie''s rennt!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Ex-Knacki, dem brauchst du nichts zu erzählen - der weiß, wie der Hase läuft!\"  2. Das ist ein Häfenbruder, der hat seine Runden gedreht – den musst du nicht briefen, der kennt das Spiel!  3. Das ist ein Mehrfachvorbestrafter, der hat mehr Knasterfahrung als wir alle zusammen – also red nicht mit dem wie mit ''nem Zivi [=Zivildienstleistender]!"}]'::jsonb, ''),
  ('haass-gee', 'haass gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'heiß gehen', '[{"kategorie": "wörtlich", "text": "\"in Wut geraten\""}, {"kategorie": "", "text": "\"aus der Haut fahren\""}, {"kategorie": "", "text": "\"an die Decke gehen\";  \"in die Luft gehen\""}, {"kategorie": "", "text": "\"vor Wut die Wände hochgehen\""}, {"kategorie": "", "text": "sich aufregen, sich entrüsten, ausrasten, durchdrehen, ausflippen"}]'::jsonb, 'Do gee i haass!'),
  ('do-gee-i-haass', 'Do gee i haass!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da geh ich heiß!', '[{"kategorie": "wörtlich", "text": "\"Da platzt mir der Kragen!\"  2. Da gehe ich in die Luft!  3. Da geh ich vor Wut die Wände hoch!  4. Da geh ich ab wie ''ne Rakete!  5. Da kocht mir das Blut über!"}]'::jsonb, ''),
  ('waunnsd-eam-auf-sei-ex-aureedsd-geeda-haass', 'Waunnsd eam auf sei Ex aureedsd, geeda haass!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn du ihn auf seine Ex anredest, geht er heiß!', '[{"kategorie": "wörtlich", "text": "\"Wenn du ihn auf seine Ex ansprichst, flippt er aus!\"  2. Sprich ihn bloß nicht auf seine Ex an – da dreht er komplett durch!  3. Red ihn bloß nicht auf seine Ex an - der rastet voll aus, wenn du nur ihren Namen sagst!"}]'::jsonb, 'haass gee'),
  ('de-schleimige-oat-von-eam-woa-ma-von-aufaung-au-zwiida', 'De schleimige Oat von eam woa ma von Aufaung au zwiida!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die schleimige Art von ihm war mir von Anfang an zuwider!', '[{"kategorie": "wörtlich", "text": "\"Seine schleimige Art war mir von Anfang an unangenehm!\"  2. Ich konnte seine aufgesetzte Freundlichkeit von Anfang an nicht ausstehen!  3. Seine Schleimerei hab ich von Anfang an als ungut empfunden!  4. Ich hab ihm seine gekünstelte Freundlichkeit nie abgenommen – mir war der Typ von Anfang an nur lästig, um nicht zu sagen ''suspekt''!\""}]'::jsonb, ''),
  ('es-is-ma-echt-zwiida-owa-wos-soi-i-mochn', 'Es is ma echt zwiida, owa wos soi I mochn?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Es ist mir echt zuwider, aber was soll ich machen?', '[{"kategorie": "wörtlich", "text": "\"Es ist mir wirklich unangenehm, aber ich hab keine Wahl!\"  2. Es ist mir äußerst peinlich, aber mir bleibt nichts anderes übrig!  3. Es ekelt mich wirklich an, aber es muss wohl sein!  4. Es geht mir total gegen den Strich, aber ich komm nicht drum rum!"}]'::jsonb, ''),
  ('i-bin-ma-soeoewa-zwiida', 'I bin ma sööwa zwiida!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich bin mir selbst zuwider', '[{"kategorie": "wörtlich", "text": "\"Ich kann mich selbst nicht ausstehen!\"  2. Ich widere mich selbst an!  3. Ich kann mich selbst nicht leiden!  4. Ich bin mir selbst ein Gräuel!"}]'::jsonb, ''),
  ('olle-menschn-san-ma-zwiida', 'Olle Menschn san ma zwiida!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alle Menschen sind mir zuwider!', '[{"kategorie": "wörtlich", "text": "\"Mich widern alle Menschen an!\"  2. Ich verabscheue alle Menschen!  3. Mir sind alle Menschen verhasst!"}]'::jsonb, ''),
  ('des-mentsch-is-ned-zwiida', 'Des Mentsch is ned zwiida!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Das Mentsch ist nicht zuwider!', '[{"kategorie": "wörtlich", "text": "\"Die Kleine ist nicht unsympathisch!\"  2. Das Mädel kann man anschauen, auf jeden Fall!  3. Das Mädel wirkt echt nett - die geht schon klar!"}]'::jsonb, ''),
  ('a-zwiidara-keal', 'A zwiidara Keal!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ein zwiderer Kerl!', '[{"kategorie": "wörtlich", "text": "\"Ein unsympathischer Kerl!\"  2. \"Ein unguter Bursche!\"  3. \"Ein höchst unangenehmer Zeitgenosse!\""}]'::jsonb, ''),
  ('a-zwiidare-gschichd', 'A zwiidare Gschichd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Eine zwidere Geschichte!', '[{"kategorie": "wörtlich", "text": "\"Eine leidige Geschichte!\"  2. \"Eine üble Geschichte!\"  3. \"Eine höchst ungute Geschichte!\""}]'::jsonb, ''),
  ('da-hund-valiad-so-vueue-poeoez-do-kunntad-ma-an-daeaewich-draus-mochn', 'Da Hund valiad so vüü Pööz - do kunntad ma an Dääwich draus mochn!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Der Hund verliert so viel Pelz - da könnte man ''nen Teppich draus machen!', '[{"kategorie": "wörtlich", "text": "\"Der Hund verliert so viel Fell - da könnte man ''nen Teppich draus machen!\"  2. Der Hund lässt so viel Haare, dass man einen Teppich daraus machen könnte!  3. Der Köter verliert so viel Pelz, da wird selbst ein Biber neidisch!"}]'::jsonb, ''),
  ('i-schwea-da-dei-poeoez-leebd-noo-i-hob-eam-grod-fauchn-ghead', 'I schwea da, dei Pööz leebd noo - I hob eam grod fauchn ghead!', '', '', '', 'Echte Wiener Schmähperlen', 'Ich schwör dir, dein Pelz lebt noch - ich hab ihn grad fauchen gehört!', '[{"kategorie": "wörtlich", "text": "\"Ich hab''s grad scharren gehört - ich glaub, dein Pelzmantel lebt noch und das Tier will raus!\"  2. \"Ich glaub, ich hab deinen Pelzmantel grad knurren gehört – pass auf, denn das Tier da drin hat vielleicht mehr Zähne als seine Trägerin!  \"  3. Ich schwör dir, dein Pelzmantel lebt noch - ich wart nur noch drauf, dass er mir s''Pfötchen gibt!"}]'::jsonb, ''),
  ('de-hod-a-poeoezgschaefd-zwischn-de-fiass-wiara-biiba', 'De hod a Pöözgschäfd zwischn de Fiass wiara Biiba!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die hat ein Pelzgeschäft zwischen den Beinen wie ein Biber!', '[{"kategorie": "wörtlich", "text": "\"Die hat einen Pelzteppich zwischen den Beinen wie ein Biber!\"  \"Die hat ''ne Intimbehaarung wie ein Biberfell - der reinste Dschungel zwischen ihren Beinen!\"  3. \"Die hat ''ne Pelzfabrik im Schambereich - dichtes Fell, ganz Natur, voll Bio!\""}]'::jsonb, ''),
  ('aussaschaun-wiara-juud-ausn-poeoezgschaefd', 'aussaschaun wiara Juud ausn Pöözgschäfd', '', '', '', 'Wiener Gaunersprache', 'rausschauen wie ein Jude aus dem Pelzgeschäft', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"still und leise herausschauen\", \"heimlich herausgucken\", \"unbemerkt hervorlinsen\", \"hyperwachsam hervorlugen\", \"misstrauisch beobachten\", \"heimlich die Umgebung ausspähen\" (=\"heimlich, vorsichtig, versteckt und hyperwachsam herausschauen, etwa durch eine Tür, ein Fenster, aus einem Versteck oder einem Raum – mit einem gewissen Argwohn oder Berechnung, oft mit einem humorvoll-abwertenden Unterton)"}]'::jsonb, 'Dea pickd in gaunzn Toog hintan Vuahaung und schaud aussa wiara Juud ausn Pöözgschäfd, ob eam wea wos flaadad!'),
  ('dea-pickd-in-gaunzn-toog-hintan-vuahaung-und-schaud-aussa-wiara-juud-ausn-poeoezgschaefd-ob-eam-wea-wos-flaadad', 'Dea pickd in gaunzn Toog hintan Vuahaung und schaud aussa wiara Juud ausn Pöözgschäfd, ob eam wea wos flaadad!', '', '', '', 'Wiener Gaunersprache', 'Der pickt den ganzen Tag hinter''m Vorhang und schaut raus wie ein Jud'' aus dem Pelzgeschäft, ob ihm wer was fladert!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Der hockt den ganzen Tag hinter’m Vorhang und schielt raus wie ein Jude aus dem Pelzgeschäft, der Angst hat, dass ihm einer seine Ware klaut!\"  2. \"Der hängt ständig hinter’m Vorhang und späht raus wie ein Schließer auf Kontrollgang, ob net wer was mitgehen lässt!\"  3. Der pickt dort drinnen wie ein Spanner im Dunkeln und beobachtet jeden, der vorbeigeht, als würd ihm gleich wer die ganze Bude ausräumen!"}]'::jsonb, 'aussaschaun wiara Juud ausn Pöözgschäfd'),
  ('dea-sitzd-aum-fenstabaangl-und-schaud-aussa-wiara-juud-ausn-poeoezgschaefd', 'Dea sitzd aum Fenstabaangl und schaud aussa wiara Juud ausn Pöözgschäfd!', '', '', '', 'Wiener Gaunersprache', 'Der sitzt an der Fensterbank und schaut raus wie ein Jud aus dem Pelzgeschäft!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Der sitzt an der Fensterbank und guckt still und heimlich heraus wie ein Jude aus dem Pelzgeschäft!\"  2. Der sitzt an der Fensterbank und späht die Umgebung still und leise aus!  3. Er hockt an der Fensterbank und sucht die Umgebung mit seinen Blicken heimlich ab!"}]'::jsonb, ''),
  ('wos-schaut-fia-mi-dabei-aussa', 'Wos schaut fia mi dabei aussa?', '', '', '', 'Wiener Gaunersprache', 'Was schaut für mich dabei raus?', '[{"kategorie": "wörtlich", "text": "\"Was springt für mich dabei raus?\"  2. Was ist für mich dabei drin?  3. Was kommt für mich dabei rum?"}]'::jsonb, ''),
  ('an-poeoezaeamae-scheissn', 'an Pöözäamä scheissn', '', '', '', 'Echte Wiener Schmähperlen', 'einen Pelzärmel scheißen', '[{"kategorie": "wörtlich", "text": "\"eine pelzbedeckte Kackwurst ausscheißen\""}, {"kategorie": "", "text": "\"einen Pelzärmel legen\""}, {"kategorie": "", "text": "\"eine Stange kacken\""}, {"kategorie": "", "text": "[[eine]] Wurzen scheißen"}, {"kategorie": "", "text": "\"einen [[Pilzling]] mit Pelzbehaarung gebären\""}]'::jsonb, 'Waunnsd den sei Gulasch issd, scheissd noocha ka Wuazn mea, sondan an Pöözäamä mit Schuitapoista!'),
  ('waunnsd-den-sei-gulasch-issd-scheissd-noocha-ka-wuazn-mea-sondan-an-poeoezaeamae-mit-schuitapoista', 'Waunnsd den sei Gulasch issd, scheissd noocha ka Wuazn mea, sondan an Pöözäamä mit Schuitapoista!', '', '', '', 'Echte Wiener Schmähperlen', 'Wenn du das Gulasch von ihm isst, dann scheißt du nachher keine Wurzen mehr, sondern einen Pelzärmel mit Schulterpolster!', '[{"kategorie": "wörtlich", "text": "\"Wenn du sein Gulasch frisst, kommt hinten kein Haufen, sondern eine pelzbedeckte Kackwurst raus!\"  2. Iss sein Gulasch – und du gebierst nachher einen Pilzling mit Pelzbehaarung!  3. Wer dieses Gulasch isst, scheißt nachher eine brennend-braune Pelzbanane raus!"}]'::jsonb, 'an Pöözäamä scheissn'),
  ('an-aeamae-scheissn', 'an Äamä scheissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Ärmel scheißen', '[{"kategorie": "wörtlich", "text": "\"eine Kackwurst ausscheiden\""}, {"kategorie": "", "text": "\"einen Ärmel legen\""}, {"kategorie": "", "text": "\"eine Stange kacken\""}, {"kategorie": "", "text": "[[einen]] Pelzärmel scheißen"}, {"kategorie": "", "text": "[[einen Pilzling gebären]]"}]'::jsonb, ''),
  ('waunnsd-den-sei-gulasch-issd-scheissd-noocha-ka-wuazn-mea-sondan-an-aeamae-mit-schuitapoista', 'Waunnsd den sei Gulasch issd, scheissd noocha ka Wuazn mea, sondan an Äamä mit Schuitapoista!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn du das Gulasch von ihm isst, dann scheißt du nachher keine Wurzen mehr, sondern einen Ärmel mit Schulterpolster!', '[{"kategorie": "wörtlich", "text": "\"Wenn du sein Gulasch frisst, kommt hinten kein Haufen merh raus, sondern eine pelzbedeckte Kackwurst!\"  2. Iss sein Gulasch – und du gebierst nachher einen Pilzling mit Pelzbehaarung!  3. Wer dieses Gulasch isst, scheißt nachher eine brennend-braune Pelzbanane raus!"}]'::jsonb, 'an Äamä scheissn'),
  ('a-wuazn-scheissn', 'a Wuazn scheissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine Wurzen scheißen', '[{"kategorie": "wörtlich", "text": "\"eine Kackwurzel ausscheiden\""}, {"kategorie": "", "text": "\"einen Ärmel legen\""}, {"kategorie": "", "text": "\"eine Stange kacken\""}, {"kategorie": "", "text": "[[einen]] Pelzärmel scheißen"}, {"kategorie": "", "text": "[[einen Pilzling gebären]]"}]'::jsonb, ''),
  ('noochn-reeng-san-iwaroi-klaane-pueuesling-ausn-boodn-gschossn', 'Noochn Reeng san iwaroi klaane Püüsling ausn Boodn gschossn!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Nach dem Regen sind überall kleine Pilzlinge aus dem Boden geschossen!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Regen sprossen überall kleine Pilze aus dem Boden!\"  2. Nach dem warmen Regen hob sich der Waldboden – und überall blickten kleine Pilzköpfe heraus!  3. Wie winzige Schirme durchstießen die Pilzlinge nach dem Regen die nasse Erde!"}]'::jsonb, ''),
  ('do-kummd-da-pueuesling-wiida-augrauschd-waungan-wia-zwaa-geamkneedln', 'Do kummd da Püüsling wiida augrauschd - Waungan wia zwaa Geamkneedln!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da kommt der Pilzling wieder angerauscht – Wangen wie zwei Germknödel!', '[{"kategorie": "wörtlich", "text": "\"Da kommt das Pausbackengesicht wieder anmaschiert – Wangen wie zwei Hefeknödel!\"  2. Da kommt er wieder angerauscht - unser Grinsemännchen mit den Knödelbäckchen!  3. Da wackelt er wieder daher - das knuffige Mondgesicht mit den vollen Pausbäckchen!\""}]'::jsonb, ''),
  ('an-pueuesling-gebaean', 'an Püüsling gebäan', '', '', '', 'Echte Wiener Schmähperlen', 'einen Pilzling gebären', '[{"kategorie": "wörtlich", "text": "\"eine Pilzwurst scheißen\""}, {"kategorie": "", "text": "\"eine Kackwurst ausscheiden\""}, {"kategorie": "", "text": "\"einen Pilzärmel legen\""}, {"kategorie": "", "text": "\"eine Pilzstange kacken\""}, {"kategorie": "", "text": "[[einen Pelzärmel scheißen]]"}]'::jsonb, ''),
  ('waunnsd-dera-ia-schwammalgulasch-issd-scheissd-noocha-ka-wuazn-mea-na-do-gebiasd-an-gaunzn-pueuesling', 'Waunnsd dera ia Schwammalgulasch issd, scheissd noocha ka Wuazn mea - na, do gebiasd an gaunzn Püüsling!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn du das Schwammerlgulasch von ihr isst, dann scheißt du nachher keine Wurzen mehr - nein, da gebierst du einen ganzen Pilzling!', '[{"kategorie": "wörtlich", "text": "\"Wenn du ihr Pilzgulasch frisst, kommt hinten kein Haufen mehr raus, sondern ein ganzer Pilzkopf!\"  2. Iss ihr Schwammerlgulasch – und du gebierst nachher einen Pilzling mit Pelzbehaarung!  3. Wer dieses Schwammerlgulasch isst, scheißt nachher ''ne brennend-braune Pilzwurst raus!"}]'::jsonb, ''),
  ('i-soog-da-des-poeoezdackal-is-ned-kaufd-des-is-dagaunad-daschnoad-oda-daliabd', 'I soog da, des Pöözdackal is ned kaufd - des is dagaunad, daschnoad oda daliabd!', '', '', '', 'Wiener Gaunersprache', 'Ich sag dir, das Pelzdeckchen is nicht gekauft – das ist dergaunert, derschnorrt oder derliebt!', '[{"kategorie": "wörtlich", "text": "\"Ich sag dir, der Pelzmantel ist nicht gekauft – der ist ergaunert, erschnorrt oder erliebt!\"  2. Ich schwör dir, den Pelz hat sie nicht bezahlt – den hat sie sich ergaunert, erbettelt oder ervögelt!  3. Glaub mir, für den Pelzmantel hat sie keinen Cent bezahlt – nur fünfmal g’lacht und dreimal pudert!"}]'::jsonb, ''),
  ('i-schdee-auf-mandln-mit-a-bissl-wos-im-gsicht-so-a-poeoezgoschn-mochd-an-eindruck', 'I schdee auf Mandln mit a bissl wos im Gsicht - so a Pöözgoschn mochd an Eindruck!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich steh auf Mandl''n mit ein bisschen was im Gesicht – so eine Pelzgoschen macht echt ''nen Eindruck!', '[{"kategorie": "wörtlich", "text": "\"Ich steh auf Männer mit ein bisschen was im Gesicht – so ein Bart rund um den Mund macht schon Eindruck!\"  2. Ich find’s sexy, wenn Männer ''nen ordentlichen Bart tragen - da schau ich gleich zweimal hin!  3. Ich steh auf Bart – denn mit ''nem Bart schaut ein Mann gleich erwachsener aus, und das hat was!"}]'::jsonb, ''),
  ('olle-song-poeoezgoschn-zu-eam-waeu-waunna-reed-siichsd-nua-sein-poeoez-woogln-und-de-goschn-is-iagendwo-dahinta', 'Olle song ''Pöözgoschn'' zu eam - wäu waunna reed, siichsd nua sein Pööz woogln, und de Goschn is iagendwo dahinta!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Alle sagen ''Pelzgoschen'' zu ihm - weil wenn der redet, siehst du nur seinen Pelz wackeln, und die Gosch''n ist irgendwo dahinter!', '[{"kategorie": "wörtlich", "text": "\"Alle nennen ihn nur mehr Pelzgoschn – denn wenn der redet, glaubst, da redet der Bart selber!\"  2. Bei ihm redet der Bart, nicht er selbst – man glaubt fast, er wär’s Sprachrohr vom Pelz in seinem Gesicht!  3. Man nennt ihn ''Pelzgoschen\", weil bei ihm wackelt ständig die Gesichtsbehaarung - aber ob das ein Mensch ist oder ein sprechender Teppich, ist noch ungeklärt!"}]'::jsonb, ''),
  ('heit-bin-i-aufgwochd-mit-aana-poeoezgoschn-und-nui-aunung-wiar-i-ind-harpfn-kumma-bin', 'Heit bin I aufgwochd mit aana Pöözgoschn und nui Aunung, wiar I ind Harpfn kumma bin!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Heute bin ich aufgewacht mit ''ner Pelzgosch''n und null Ahnung, wie ich in die Harpfen gekommen bin!', '[{"kategorie": "wörtlich", "text": "\"Heute bin ich aufgewacht mit ''ner Pelzzunge und null Ahnung, wie ich ins Bett gekommen bin!\"  2. Ein Mund voller Pelz, ein Kopf voller Leere – und ein Fragezeichen, wie ich hier gelandet bin!  3. Ich kenn mein Bett und ich kenn meinen Mund - aber wie ich mit der Plüschtierzunge da gelandet bin, weiß ich nicht mehr!"}]'::jsonb, ''),
  ('a-guada-poeoeza-kennd-aa-jeeds-foeoe-und-siichd-mit-aan-blick-woechanes-si-zum-mauntl-zua-koppn-oda-zum-fuada-varoaweidn-lossd', 'A guada Pööza kennd aa jeeds Föö und siichd mit aan Blick, wöchanes si zum Mauntl, zua Koppn oda zum Fuada varoaweidn lossd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Ein guter Pelzer kennt jedes Fell und sieht mit einem Blick, welches sich zum Mantel, zur Mütze oder zum Futter verarbeiten lässt!', '[{"kategorie": "wörtlich", "text": "\"Ein erfahrener Pelzer kennt jedes Fell und weiß sofort, wofür es sich am besten eignet – sei es für Mantel, Mütze oder Futter!\"  2. Ein echter Pelzer liest das Fell wie ein Buch – und weiß sofort, ob daraus ein Mantel wird oder bloß ein warmer Kragen!  3. Mit geschultem Blick sieht der erfahrene Pelzer sofort, ob das Fell den Körper wärmen, den Kopf zieren oder den Saum füttern soll!"}]'::jsonb, ''),
  ('schdee-endlich-auf-du-oida-poeoeza-da-toog-woat-ned-auf-di', 'Schdee endlich auf, du oida Pööza - da Toog woat ned auf di!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Steh endlich auf, du alter Pelzer – der Tag wartet nicht auf dich!', '[{"kategorie": "wörtlich", "text": "\"Raus aus den Federn, du alter Faulpelz – draußen wartet das Leben!\"  2. Steh auf, du fauler Dauerchiller – es gibt was zu tun!  3. Auf, du alter Tachinierer - der Tag ruft!"}]'::jsonb, ''),
  ('unsa-fredl-des-is-a-echta-poeoeza-dea-vapassd-da-a-bauschdoeoengsichd-in-nui-komma-nix', 'Unsa Fredl, des is a echta Pööza - dea vapassd da a Bauschdööngsichd in nui komma nix!', '', '', '', 'Wiener Gaunersprache', 'Unser Fredl, das ist ein echter Pelzer - der verpasst dir ein Baustellengesicht in null komma nix!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Unser Fredl ist ein Haudrauf vom Feinsten – der macht aus deinem Gesicht ''ne Dauerbaustelle, bevor du blinzeln kannst!\"  2. Unser Fredl hat Hände wie ein Betonmischer – der macht aus deiner Fresse in drei Sekunden eine Dauerbaustelle!  3. Unser Fredl ist ’ne echte Abrissbirne auf zwei Beinen – der macht aus deiner Visage in Rekordzeit ''ne Dauerbaustelle!"}]'::jsonb, ''),
  ('poeoezn2', 'pöözn2', '', '', '', 'Grundwortschatz Wienerisch', 'pelzen', '[{"kategorie": "wörtlich", "text": "\"pelzen\" (vom mittelhochdeutschen \"belzen\"=\"den Pelz abziehen\")"}, {"kategorie": "hist., Handwerk", "text": "\"mit (einem) Fell bekleiden\", mit Pelz besetzen, ausfüttern"}, {"kategorie": "fig., intransitiv", "text": "\"auf der faulen Haut liegen\", \"faulenzen\", \"chillen\", \"abhängen\", [[tachinian]], [[owezaan]]"}, {"kategorie": "Gaunersprache, transitiv", "text": "\"jemandem den Pelz versohlen\", jemanden schlagen, prügeln, dreschen, verhauen, zusammenschlagen, [[döögln]]"}, {"kategorie": "Gaunerjargon", "text": "\"sich gegenseitig den Pelz versohlen\", sich schlagen, sich prügeln, [[si]] döögln"}]'::jsonb, ''),
  ('mei-mauntl-is-poeoezd-vom-kroong-bis-zum-saum', 'Mei Mauntl is pöözd - vom Kroong bis zum Saum!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mein Mantel ist gepelzt - vom Kragen bis zum Saum!', '[{"kategorie": "wörtlich", "text": "\"Mein Mantel ist vom Kragen bis zum Saum mit Pelz besetzt!\"  2. Mein Mantel ist vollständig mit Pelz gefüttert – vom Kragen bis zum Saum!  3. Vom Kragen bis hinab zum letzten Saum ziert feinster Pelz meinen dicken Wintermantel!"}]'::jsonb, ''),
  ('wia-hackln-wia-de-blaeaedn-und-dea-poeoezd-dahaam-in-da-haengemattn', 'Wia hackln wia de Bläädn, und dea pöözd dahaam in da Hängemattn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wir hackeln wie die Blöden, und der pelzt daheim in der Hängematte!', '[{"kategorie": "wörtlich", "text": "\"Wir schuften wie die Verrückten, und der liegt zu Hause in der Hängematte und chillt!\"  2. Wir reißen uns den Arsch auf, und der liegt daheim auf der faulen Haut!  3. Wir schuften wie die Trottel, und der lässt sich zu Hause die Sonne auf den Bauch scheinen!"}]'::jsonb, ''),
  ('dea-poeoezd-si-vuar-aana-jeedn-hockn', 'Dea pöözd si vuar aana jeedn Hockn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der pelzt sich vor einer jeden Hacken!', '[{"kategorie": "wörtlich", "text": "\"Der drückt sich vor jeder Arbeit!\"  2. Der macht um jede Arbeit einen weiten Bogen!  3. Der hat nur zwei Gänge: liegen und chillen!"}]'::jsonb, 'si pöözn'),
  ('de-poeoezn-si-weng-aan-jeedn-schaas-sogoa-ums-letzde-wuuzlpapia', 'De pöözn si weng aan jeedn Schaas - sogoa ums letzde Wuuzlpapia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die pelzen sich wegen einem jeden Schas – sogar ums letzte Wuzelpapier!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Die pelzen sich um jeden Scheiß – sogar ums letzte Zigarettenpapier!\"  2. (Deutschland): \"Die kloppen sich echt wegen jedem Dreck – selbst ums letzte Kippenpapier!\"  3. Die dögeln sich echt wegen jedem Scheiß – sogar ums letzte Blatt Zigarettenpapier!"}]'::jsonb, 'si pöözn'),
  ('si-poeoezn', 'si pöözn', '', '', '', 'Grundwortschatz Wienerisch', 'sich pelzen', '[{"kategorie": "wörtlich", "text": "\"sich pelzen\" (vom mittelhochdeutschen \"belzen\"=\"den Pelz abziehen\")"}, {"kategorie": "allg.", "text": "\"sich auf die faule Haut legen\", \"sich schonen\", \"sich vor etwas drücken\""}, {"kategorie": "Gaunerjargon", "text": "\"sich gegenseitig den Pelz versohlen\", sich schlagen, sich prügeln, [[si]] döögln"}]'::jsonb, 'si döögln'),
  ('den-schdangla-hod-a-nua-noo-einedruckn-miassn', 'Den Schdangla hod a nua noo einedruckn miassn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Den Stangler hat er nur noch reindrücken müssen!', '[{"kategorie": "wörtlich", "text": "\"Den Stanglpass musste er nur noch über die Linie drücken!\"  2. Er musste den Querpass vor das Tor nur noch reinschieben!  3. Der Stanglpass kam punktgenau – er musste nur noch den Fuß hinhalten!"}]'::jsonb, ''),
  ('a-schdangla-hod-kan-bock-aufd-schui-dea-sitzd-liawa-im-park-ois-im-klassnzimma', 'A Schdangla hod kan Bock aufd Schui - dea sitzd liawa im Park ois im Klassnzimma!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ein Stangler hat keinen Bock auf Schule - der sitzt lieber im Park als im Klassenzimmer!', '[{"kategorie": "wörtlich", "text": "\"Ein Unterrichtsverweigerer pfeift auf die Schule – der chillt lieber auf der Parkbank als im Klassenzimmer zu sitzen!\"  2. Ein echter Schuldrückeberger meidet die Schule wie die Pest und hängt lieber draußen rum!  3. Schulschwänzer sitzen nicht in der Klasse, sondern in der Sonne!"}]'::jsonb, ''),
  ('fia-de-gaunzn-schdaagla-is-da-haeaefn-nuara-klaana-kuazualaub', 'Fia de gaunzn Schdaagla is da Hääfn nuara klaana Kuazualaub!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Für die ganzen Stagler ist der Häf''n nur ein kleiner Kurzurlaub!', '[{"kategorie": "wörtlich", "text": "\"Für die ganzen Diebe und Kleinkriminellen ist das Gefängnis nur ein kleiner Kurzurlaub!\"  2. Für Kleinkriminelle ist der Knast oft eher ein kurzer Boxenstopp als eine Strafe!  3. De Häf''n ist für Kleinkriminelle oft ''ne willkommene Auszeit vom stressigen Diebsleben – fast wie Sommerfrische!"}]'::jsonb, ''),
  ('da-direx-hod-drei-schdaagla-beim-eisschleckn-im-park-darwischd', 'Da Direx hod drei Schdaagla beim Eisschleckn im Park darwischd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Der Direx hat drei Stagler beim Eisschlecken im Park erwischt!', '[{"kategorie": "wörtlich", "text": "\"Der Direktor hat drei Schulschwänzer beim Eisschlecken im Park erwischt!\"  2. Drei Schulstangler wurden vom Direktor in flagranti erwischt - Eis schleckend im Park!  3. Drei Schulverweigerer haben sich vom Direktor höchstpersönlich erwischen lassen - noch dazu Eis schleckend im Park!"}]'::jsonb, ''),
  ('ois-notorischa-schuischdangla-waass-a-gaunz-genau-wia-ma-a-jeede-luckn-im-system-bestmeeglich-ausnutzd', 'Ois notorischa Schuischdangla waass a gaunz genau, wia ma a jeede Luckn im System bestmeeglich ausnutzd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Als notorischer Schulstangler weiß er genau, wie man jede Lücke im System bestmöglich ausnutzt!', '[{"kategorie": "wörtlich", "text": "\"Als notorischer Schulstangler hat er gelernt, jede Lücke im System bestmöglich auszunutzen!\"  2. Als eingefleischter Schulstangler weiß er genau, wie man jede Schwachstelle im System am besten ausnutzt!  3. Als erfahrener Schulstangler findet er zuverlässig jeden Schlupfwinkel im Schulbetrieb!"}]'::jsonb, ''),
  ('fiaran-schuischdaagla-zoeoen-foeoeschdundn-easchd-waunna-dawischd-wiad', 'Fiaran Schuischdaagla zöön Fööschdundn easchd, waunna dawischd wiad!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Für einen Schulstagler zählen Fehlstunden erst, wenn er erwischt wird!', '[{"kategorie": "wörtlich", "text": "\"Für einen Schulstangler gelten Fehlstunden erst, wenn er auf frischer Tat ertappt wird!\"  2. Für einen Schulschwänzer ist jede versäumte Stunde straffrei – solange keiner nachfragt!  3. Für Schulstangler ist Schwänzen erst dann schlimm, wenn’s auffliegt!"}]'::jsonb, ''),
  ('schdangl-ma-d-schui', 'Schdangl ma d''Schui!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Stangeln wir die Schule!', '[{"kategorie": "wörtlich", "text": "\"Schwänzen wir die Schule!\"  2. Lasst uns blau machen!  3. Lassen wir den Unterricht sausen!"}]'::jsonb, ''),
  ('kaum-isar-aum-bock-schdanglda-de-schdrossn-owe-wiarin-teifae-sei-haaza', 'Kaum isar aum Bock, schdanglda de Schdrossn owe wiarin Teifä sei Haaza!', '', '', '', 'Wiener Mechaniker-Slang', 'Kaum ist er am Bock, stangelt er die Straße runter wie der Heizer vom Teufel!', '[{"kategorie": "wörtlich", "text": "\"Kaum sitzt er im Sattel, jagt er die Straße runter wie ein Wilder auf zwei Rädern!\"  2. Kaum am Bock, fräst er die Straße runter, als hätte ihn der Teufel persönlich angeschoben!  3. Kaum auf dem Bike, ballert er die Bahn runter wie des Teufels Höllenheizer!"}]'::jsonb, ''),
  ('schdangln-is-wia-schbuat-nua-dass-da-puis-vom-gas-kummd-und-ned-vom-rennan', 'Schdangln is wia Schbuat - nua dass da Puis vom Gas kummd und ned vom Rennan!', '', '', '', 'Wiener Mechaniker-Slang', 'Stangeln ist wie Sport – nur dass der Puls vom Gas kommt und nicht vom Rennen!', '[{"kategorie": "wörtlich", "text": "\"Stangeln ist wie Sport – nur dass die Herzfrequenz vom Drehgriff kommt und nicht vom Laufen!\"  2. Stangeln ist wie Sport – der Asphalt wird zur Laufbahn, das Gas zur Herzpumpe!  3. Stangeln ist wie Sport – nur dass der Puls vom Gasstoß kommt und nicht vom Laufen!"}]'::jsonb, ''),
  ('friara-hoda-ollawaeu-wos-gschdaagld-heit-schaamda-si-dafia', 'Friara hoda ollawäu wos gschdaagld - heit schaamda si dafia!', '', '', '', 'Wiener Gaunersprache', 'Früher hat er alleweil was gestagelt, heute schämt er sich dafür!', '[{"kategorie": "wörtlich", "text": "\"Früher hat er ständig was geklaut, heute schämt er sich dafür!\"  2. Früher hat er dauernd was abgestaubt, heute hält er’s für peinlich!  3. Früher war er ständig am Klauen, doch inzwischen bereut er das!"}]'::jsonb, ''),
  ('eigentlich-woit-ma-nuara-schdund-schdaagln-owa-daunn-is-a-gaunza-toog-draus-wuan', 'Eigentlich woit ma nuara Schdund schdaagln - owa daunn is a gaunza Toog draus wuan!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Eigentlich wollten wir nur eine Stunde stageln - aber dann ist ein ganzer Tag draus geworden!', '[{"kategorie": "wörtlich", "text": "\"Eigentlich wollten wir nur eine Stunde blau machen – aber am Ende  haben wir den kompletten Schultag geschwänzt!\"  2. Wir wollten den Unterricht eigentlich nur für eine Stunde sausen lassen - aber irgendwie wurde daraus ein ganzer Tag!  3. Eine Stunde stangeln war der Plan – aber dann haben wir den gazen Tag blau gemacht!"}]'::jsonb, ''),
  ('de-schui-schdangln', 'de Schui schdangln', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'die Schule stangeln', '[{"kategorie": "wörtlich", "text": "\"die Schule schwänzen\" (eigtl. \"die Schule [[stageln]]\", vom italienischen \"staccare\"=\"loslösen, trennen, wegnehmen\" - Die Ersetzung von „stageln“ durch „stangeln“ im Wienerischen ist ein klassisches Beispiel für Volksetymologie: Ein lautlich fremdes oder veraltetes Wort wird durch ein vertrauter klingendes, semantisch „plausibleres“ ersetzt – obwohl der Ursprung und die eigentliche Bedeutung nicht auf „Stange“ zurückgehen)"}, {"kategorie": "allg.", "text": "vom Unterricht unentschuldigt fernbleiben, blaumachen, den Unterricht sausen lassen"}]'::jsonb, ''),
  ('fiar-uns-is-schuischdangln-a-voiksschbuat-foeoen-nua-noo-de-medaeun', 'Fiar uns is Schuischdangln a Voiksschbuat - föön nua noo de Medäun!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Für uns ist Schulstangeln Volkssport - fehlen nur noch die Medaillen!', '[{"kategorie": "wörtlich", "text": "\"Für uns ist Schulstangeln quasi Volkssport – wir warten nur noch auf die Medaillen!\"  2. Für uns ist Schulstangeln Breitensport – schade, dass es keine Medaillen dafür gibt!  3. Für uns ist Schulstangeln der Volkssport Nr. 1 – einzig die Medaillen fehlen noch!"}]'::jsonb, ''),
  ('duach-de-graetzln-schdeazn-und-imma-neiche-eckn-entdeckn-des-is-sei-greessde-freid', 'Duach de Grätzln schdeazn und imma neiche Eckn entdeckn - des is sei greessde Freid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Durch die Grätzeln flanieren und immer neue Ecken entdecken - das ist seine größte Freude!', '[{"kategorie": "wörtlich", "text": "\"Seine größte Freude ist es, an Wochenenden durch die Stadtviertel zu flanieren und immer neue Ecken zu entdecken!\"  2. Nichts liebt er mehr, als am Wochenende durch die Straßen zu bummeln und verborgene Plätze zu entdecken!  3. Nichts macht ihm mehr Spaß, als am Wochenende rumzustrolchen und dabei immer wieder neue Winkel aufzuspüren!"}]'::jsonb, ''),
  ('schdeazn-gee', 'schdeazn gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'sterzen gehen', '[{"kategorie": "wörtlich", "text": "\"flanieren gehen\" (vom mittelhochdeutschen \"sterzen\"=\"umherschweifen\")"}, {"kategorie": "allg.", "text": "rumstrolchen, blaumachen, (einen Pflichttermin, etc.) auslassen, sausen lassen, schleifen lassen, schwänzen"}]'::jsonb, 'de Schui schdangln'),
  ('dea-geed-so-oft-schdeeazn-dassa-si-an-oskar-fias-wegbleibm-vadiend-haedad', 'Dea geed so oft schdeeazn, dassa si an Oskar fias Wegbleibm vadiend hädad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der geht so oft sterzen, dass er sich einen Oskar fürs Wegbleiben verdient hätte!', '[{"kategorie": "wörtlich", "text": "\"Der schwänzt so regelmäßig, dass er sich sich fast schon eine Trophäe fürs Wegbleiben verdient hätte!\"  2. Der macht so konsequent blau, dass man ihm einen Ehrenpreis fürs Unsichtbarsein überreichen könnte!  3. Der drückt sich so häufig, dass man ihm einen Preis fürs Wegdrücken verleihen müsste!"}]'::jsonb, 'schdeazn gee'),
  ('schdiazn-gee', 'schdiazn gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'stürzen gehen', '[{"kategorie": "wörtlich", "text": "\"flanieren gehen\" (eigtl. \"sterzen gehen\", vom mittelhochdeutschen \"sterzen\"=\"umherschweifen\" - Die Ersetzung von „sterzen“ durch „stürzen“ im Wienerischen ist ein klassisches Beispiel für Volksetymologie: Ein lautlich fremdes oder veraltetes Wort wird durch ein vertrauter klingendes, semantisch „plausibleres“ ersetzt – obwohl der Ursprung und die eigentliche Bedeutung nicht auf „stürzen“ zurückgehen)"}, {"kategorie": "allg.", "text": "rumstrolchen, blaumachen, (einen Pflichttermin, etc.) auslassen, sausen lassen, schleifenlassen, schwänzen"}]'::jsonb, 'Von miar aus soia a hoibe Schdund schdiazn gee - owa doch ned an gaunzn Toog!'),
  ('von-miar-aus-soia-a-hoibe-schdund-schdiazn-gee-owa-doch-ned-an-gaunzn-toog', 'Von miar aus soia a hoibe Schdund schdiazn gee - owa doch ned an gaunzn Toog!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Von mir aus soll er eine halbe Stunde stürzen gehen - aber doch nicht einen ganzen Tag!', '[{"kategorie": "wörtlich", "text": "\"Von mir aus kann er eine halbe Stunde fehlen – aber doch nicht gleich den ganzen Tag!\"  2. \"Kurz blau machen ist noch tolerierbar – aber gleich einen ganzen Tag? Das geht nicht!\"  3. Meinetwegen kann er gerne mal eine halbe Stunde schwänzen – aber doch nicht gleich den ganzen Tag!"}]'::jsonb, 'schdiazn gee'),
  ('im-schuischdeazn-isa-profi-oft-meakn-de-leara-nedamoi-mea-dassa-schoo-wiida-schdangld', 'Im Schuischdeazn isa Profi - oft meakn de Leara nedamoi mea, dassa schoo wiida schdangld!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Im Schulsterzen ist er Profi - oft merken die Lehrer nicht einmal mehr, dass er schon wieder stangelt!', '[{"kategorie": "wörtlich", "text": "\"Im Schulschwänzen ist er Profi – die Lehrer merken oft nicht einmal, dass er schon wieder fehlt!\"  2. Im Schulschwänzen ist er ein Ass – oft bemerken die Lehrer nicht einmal mehr, dass er schon wieder blau macht!  3. Die hohe Kunst des Schuleschwänzens beherrscht er perfekt – oft fällt den Lehrern nicht mal mehr auf, dass er schon wieder abgetaucht ist!"}]'::jsonb, ''),
  ('schuischdiazn-is-wos-fia-profis-nua-aufaenga-wean-dawischd', 'Schuischdiazn is wos fia Profis - nua Aufänga wean dawischd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Schulstürzen ist was für Profis - nur Anfänger werden erwischt!', '[{"kategorie": "wörtlich", "text": "\"Schuleschwänzen ist was für Profis - nur Anfänger werden erwischt!\"  2. \"Schuleschwänzen ist eine Kunst – Dilettanten fliegen auf!\"  3. Beim Schulschwänzen überleben nur die Profis – Anfänger sind Freiwild!"}]'::jsonb, ''),
  ('kaa-feind-hod-an-schuss-ausn-schdoogl-iwaleebd-waunna-sauwa-gschbaunnd-woa', 'Kaa Feind hod an Schuss ausn Schdoogl iwaleebd, waunna sauwa gschbaunnd woa!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Kein Feind hat den Schuß aus einem Stagel überlebt, wenn er sauber gespannt war!', '[{"kategorie": "wörtlich", "text": "\"Kein Feind überlebte den Schuss aus einem Stagel, so er recht gespannt war!\"  2. War der Stagel wohl gespannt, so entging ihm kein Feind unversehrt!  3. Ein Stagel, recht gespannt, ließ kaum einen Feind am Leben!"}]'::jsonb, ''),
  ('da-schdoogl-wiad-direkt-im-feia-dahitzd-und-daunn-mit-ana-zaungan-ins-beegleisn-eigsetzd', 'Da Schdoogl wiad direkt im Feia dahitzd und daunn mit ana Zaungan ins Beegleisn eigsetzd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Stagel wird direkt im Feuer erhitzt und anschließend mit einer Zange in das Bügeleisen eingesetzt!', '[{"kategorie": "wörtlich", "text": "\"Der Eisenkern wird direkt im Feuer erhitzt und anschließend mit einer Zange in das Bügeleisen eingesetzt!\"  2. Der Glühkern wird im Feuer auf Temperatur gebracht und danach vorsichtig mit einer Zange in das Bügeleisen geschoben!  3. Der rotglühende Heizeinsatz wird aus dem Feuer gehoben und direkt ins Bügeleisen eingesetzt!"}]'::jsonb, ''),
  ('gimma-s-wintabia-und-vagiss-in-schdoogl-ned-sunst-friar-i-ma-de-goschn-oo', 'Gimma s''Wintabia - und vagiss in Schdoogl ned, sunst friar I ma de Goschn oo!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Gib mir das Winterbier – und vergiss den Stagel nicht, sonst frier ich mir die Gosch''n ab!', '[{"kategorie": "wörtlich", "text": "\"Gib mir das Winterbier – und vergiss den Bierwärmer nicht, sonst friert mir der Mund ein!\"  2. Gib her das Winterbier – aber bitte mit Bierwärmestab, sonst friert mir die Schnauze ab!  3. Her mit dem Winterbier – und gib gleich den Bierheizstab rein, bevor mir die Klappe zufriert!"}]'::jsonb, ''),
  ('des-oide-eisn-is-schoo-gaunz-schdooglgrea-heechste-zeit-dass-da-a-neichs-zualeegsd', 'Des oide Eisn is schoo gaunz schdooglgrea - heechste Zeit, dass da a neichs zualeegsd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das alte Eisen ist schon ganz stagelgrün - höchste Zeit, dass du dir ein neues zulegst!', '[{"kategorie": "wörtlich", "text": "\"Das alte Heizeisen ist komplett korrodiert und grün angelaufen – höchste Zeit, dass du dir ein neues besorgst!\"  2. Der alte Bügeleisenkern ist so grün und gammelig, der gehört längst in den Schrott – leg dir ''nen neuen zu!  3. Der alte Bierwärmer setzt ja schon Grünspan an - hau ihn weg und kauf dir ''nen neuen!"}]'::jsonb, ''),
  ('wem-schdooglgrea-aufliing', 'wem schdooglgrea aufliing', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem stagelgrün aufliegen', '[{"kategorie": "wörtlich", "text": "\"jemandem wie stahlgrüne Patina auf der Haut liegen\" (in Anspielung darauf, dass das Heizeisen [[[Stagel]]] beim Erhitzen im Feuer grün anläuft)"}, {"kategorie": "fig.", "text": "\"jemandem gehörig gegen den Strich gehen\""}, {"kategorie": "", "text": "\"jemandem mehr als sauer aufstoßen\""}, {"kategorie": "", "text": "\"bei jemandem für großen Unmut sorgen\""}, {"kategorie": "", "text": "\"jemanden so richtig ankotzen\""}]'::jsonb, 'Schdooglgrea aufliing dadads ma, waunn I in Schäädl dafia hihoidn miassad!'),
  ('des-liigd-ma-schdooglgrea-auf', 'Des liigd ma schdooglgrea auf!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das liegt mir stagelgrün auf!', '[{"kategorie": "wörtlich", "text": "\"Das liegt wie stahlgrüne Patina auf meiner Haut!\" =  1. (wörtlich): \"Das stößt mir mehr als sauer auf!\"  2. \"Das ist mir durch und durch zuwider!\"  3. \"Das widert mich so richtig an!\"  4. \"Das ist mir ein echter Graus!\""}]'::jsonb, ''),
  ('schdooglgrea-aufliing-dadads-ma-waunn-i-in-schaeaedl-dafia-hihoidn-miassad', 'Schdooglgrea aufliing dadads ma, waunn I in Schäädl dafia hihoidn miassad!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Stagelgrün aufliegen täte es mir, wenn ich den Schädel dafür hinhalten müsste!', '[{"kategorie": "wörtlich", "text": "\"Es ginge mir verdammt gegen den Strich, wenn ich den Kopf dafür hinhalten müsste!\"  2. Es wäre mir äußerst zuwider, dafür die Verantwortung übernehmen zu müssen!  3. Wenn ich am Ende den Sündenbock dafür geben müsste, würde das für gehörigen Unmut bei mir sorgen!   4. \"Den Kopf dafür hinzuhalten, würde mich so richtig ankotzen!\""}]'::jsonb, ''),
  ('wem-schdoolgrea-aufschdeing', 'wem schdoolgrea aufschdeing', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem stagelgrün aufsteigen', '[{"kategorie": "wörtlich", "text": "\"jemandem wie kotzgrüne Magensäure aufsteigen\" (in Anspielung darauf, dass das Grün der Magensäure an die grüne Patina eines Heizeisens [[[Stagel]]] erinnert)"}, {"kategorie": "fig.", "text": "\"jemandem gehörig gegen den Strich gehen\""}, {"kategorie": "", "text": "\"jemandem mehr als sauer aufstoßen\""}, {"kategorie": "", "text": "\"bei jemandem für großen Unmut sorgen\""}, {"kategorie": "", "text": "\"jemanden so richtig ankotzen\""}]'::jsonb, ''),
  ('schdooglgrea-aufschdeing-dadads-ma-waunn-i-den-gaunzn-schaas-ausboodn-miassad', 'Schdooglgrea aufschdeing dadads ma, waunn I den gaunzn Schaas ausboodn miassad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Stagelgrün aufsteigen täte es mir, wenn ich den Schas ausbaden muss!', '[{"kategorie": "wörtlich", "text": "\"Mehr als sauer aufstoßen würde es mir, wenn ich den ganzen Scheiß ausbaden müsste!\"  2. Es wäre mir äußerst zuwider, dafür die Verantwortung übernehmen zu müssen!  3. Das würde mir verdammt gegen den Strich gehen, wenn ich den ganzen Schlamassel für euch ausbügeln müsste!"}]'::jsonb, 'wem schdoolgrea aufschdeing'),
  ('wem-schdooglgrea-aufschdessn', 'wem schdooglgrea aufschdessn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem stagelgrün aufstoßen', '[{"kategorie": "wörtlich", "text": "\"jemandem wie kotzgrüne Magensäure aufstoßen\" (in Anspielung darauf, dass das Grün der Magensäure an die grüne Patina eines Heizeisens [[[Stagel]]] erinnert)"}, {"kategorie": "fig.", "text": "\"jemandem gehörig gegen den Strich gehen\""}, {"kategorie": "", "text": "\"jemandem mehr als sauer aufstoßen\""}, {"kategorie": "", "text": "\"bei jemandem für großen Unmut sorgen\""}, {"kategorie": "", "text": "\"jemanden so richtig ankotzen\""}]'::jsonb, 'Schddoglgrea aufgschdessn is meina Oidn, dass I ia kaa Wuat von da Kündigung gsoogd hob!'),
  ('schddoglgrea-aufgschdessn-is-meina-oidn-dass-i-ia-kaa-wuat-von-da-kuendigung-gsoogd-hob', 'Schddoglgrea aufgschdessn is meina Oidn, dass I ia kaa Wuat von da Kündigung gsoogd hob!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Stagelgrün aufgestoßen ist es meiner Alten, dass ich ihr kein Wort von der Kündigung gesagt habe!', '[{"kategorie": "wörtlich", "text": "\"Meiner Alten ist mehr als sauer aufgestoßen, dass ich ihr nichts von der Kündigung gesagt habe!\"  2. Gar nicht geschmeckt hat meiner Frau, dass ich ihr die Kündigung verheimlicht habe!  3. Meine Alte hat es mir richtig übelgenommen, dass ich ihr nichts von der Kündigung erzählt habe!"}]'::jsonb, 'wem schdooglgrea aufschdessn'),
  ('des-is-ma-schdooglgrea-aufgschdiing', 'Des is ma schdooglgrea aufgschdiing!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist mir stagelgrün aufgestiegen', '[{"kategorie": "wörtlich", "text": "\"Das ist mir mehr als sauer aufgestoßen!\"  2. Das ist mir verdammt gegen den Strich gegangen!  3. Das hat mich extrem geärgert!  4. Das hat bei mir für großen Unmut gesorgt!\"  5. Das hat mich richtig angekotzt!"}]'::jsonb, ''),
  ('noochn-schmiidn-wiads-metoi-sofuat-gschdoogld', 'Noochn Schmiidn wiads Metoi sofuat gschdoogld!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Nach dem Schmieden wird das Metall sofort gestagelt!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Schmieden wird das Metall sofort gehärtet!\"  2. Nach dem Schmieden wird das Werkstück direkt wärmebehandelt!  3. Nach dem Schmieden wird das Metall ohne Verzögerung temperiert!"}]'::jsonb, ''),
  ('a-gschdooglds-bia', 'a gschdooglds Bia', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'ein gestageltes Bier', '[{"kategorie": "wörtlich", "text": "\"ein mit einem Stagel [Bierwärmer] vorgewärmtes Bier\""}, {"kategorie": "", "text": "\"ein mit Heizeinsatz warm gemachtes Bier\""}, {"kategorie": "", "text": "\"ein angewärmtes Kaltgetränk\""}]'::jsonb, ''),
  ('nua-woamduuscha-saufn-a-gschdoogls-bia', 'Nua Woamduuscha saufn a gschdoogls Bia!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Nur Warmduscher saufen ein gestageltes Bier!', '[{"kategorie": "wörtlich", "text": "\"Nur Warmduscher trinken Bier mit Wärmestab!\"  2. \"Nur Weicheier lassen sich ihr Bier mit einem Bierwärmer servieren!\"  3. \"Nur Schlappschwänze bestellen sich ein vorgewärmtes Bier!\""}]'::jsonb, 'a gschdooglds Bia'),
  ('den-neichn-miassma-easchd-a-weng-auschdoogln-wiast-seeng-daunn-reed-a-wiara-woeoedmaasta', 'Den Neichn miassma easchd a weng auschdoogln - wiast seeng, daunn reed a wiara Wöödmaasta!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Den Neuen müssen wir erst ein wenig anstageln - wirst sehen, dann redet er wie ein Weltmeister!', '[{"kategorie": "wörtlich", "text": "\"Den Neuen müssen wir erst ein wenig mit Alkohol anwärmen - wirst sehen, dann redet er wie ein Wasserfall!\"  2. Den Neuen müssen wir erst ein bisschen rauschig machen - wirst sehen, dann sprudeln die Wörter nur so raus aus ihm!  3. Den Neuen müssen wir erst auf Betriebstemperatur bringen - wirst sehen, dann löst sich der Rost von seiner Zunge!"}]'::jsonb, ''),
  ('dem-foeoed-goa-nix-dea-tachiniad-nua', 'Dem fööd goa nix, dea tachiniad nua!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dem fehlt gar nichts, der tachiniert nur!', '[{"kategorie": "wörtlich", "text": "\"Dem fehlt gar nichts, der drückt sich bloß vor der Arbeit!\"  2. Dem fehlt gar nichts, der will nur eine ruhige Kugel schieben!  3. Der ist kerngesund, der stellt sich bloß krank!"}]'::jsonb, ''),
  ('dei-tachiniirarei-is-fueuemreif', 'Dei Tachiniirarei is füümreif!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Deine Tachniererei ist filmreif!', '[{"kategorie": "wörtlich", "text": "\"Deine Drückebergerei ist filmreif!\"  2. Dein Talent zur Drückebergerei ist Oscar-verdächtig!  3. Deine Kunst, dich wegzuducken, ist wahrhaft filmreif!"}]'::jsonb, ''),
  ('des-is-a-tachiniira-wiara-im-biachl-schdeed', 'Des is a Tachiniira wiara im Biachl schdeed!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist ein Tachnierer, wie er im Buche steht!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Drückeberger, wie er im Buche steht!\"  2. Der ist ein fauler Hund durch und durch!  3. Der drückt sich vor jeder Arbeit!  4. Der jammert, sobald er auch nur einen Finger bewegt!  5. [[Dea]] brichd si de Finga beim Noosnbuan!"}]'::jsonb, ''),
  ('dea-hod-de-tachinitis-seita-auf-da-woeoed-is', 'Dea hod de Tachinitis, seita auf da Wööd is!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der hat die Tachinose, seit er auf der Welt ist!', '[{"kategorie": "wörtlich", "text": "\"Der hat die Drückerbergerkrankheit, seit er auf der Welt ist!\"  2. Der leidet an Arbeitsverweigerung, seit er auf der Welt ist!  3. Das ist ein geborener [[Owezaara]]!  4. Dem wurde die Drückebergerei mit der Muttermilch eingeflößt!"}]'::jsonb, ''),
  ('dea-hod-de-tachinose-seita-auf-da-woeoed-is', 'Dea hod de Tachinose, seita auf da Wööd is!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat die Tachinose, seit er auf der Welt ist!', '[{"kategorie": "wörtlich", "text": "\"Der hat die Drückerbergerkrankheit, seit er auf der Welt ist!\"  2. Der leidet an Arbeitsverweigerung, seit er auf der Welt ist!  3. Das ist ein geborener [[Owezaara]]!  4. Dem wurde die Drückebergerei mit der Muttermilch eingeflößt!"}]'::jsonb, ''),
  ('dea-hod-heit-de-tachinose', 'Dea hod heit de Tachinose!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der hat heute die Tachinose!', '[{"kategorie": "wörtlich", "text": "\"Der leidet heute an der Drückebergerkrankheit!\"  2. \"Der hat heute das Drückebergersyndrom!\"  3. \"Der leidet heute an spontaner Arbeitsunverträglichkeit!\""}]'::jsonb, ''),
  ('dea-hod-heit-de-tachinitis', 'Dea hod heit de Tachinitis!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat heute die Tachinitis!', '[{"kategorie": "wörtlich", "text": "\"Der leidet heute an der Drückebergerkrankheit!\"  2. \"Der hat heute das Drückebergersyndrom!\"  3. \"Der leidet heute an spontaner Arbeitsunverträglichkeit!\""}]'::jsonb, ''),
  ('wia-ma-so-an-traumpae-heiratn-kau-is-ma-a-raeaetsl', 'Wia ma so an Traumpä heiratn kau, is ma a Räätsl!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wie man so einen Trampel heiraten kann, ist mir ein Rätsel!', '[{"kategorie": "wörtlich", "text": "\"Wie man so ein grobschlächtiges Frauenzimmer heiraten kann, ist mir ein Rätsel!\"  2. Wie man so ein Trampeltier zur Frau nehmen kann, ist mir unerklärlich!  3. Mit so einer Dumpfbacke verheiratet zu sein, kann ich mir beim besten Willen nicht vorstellen!"}]'::jsonb, ''),
  ('so-a-traumpae-von-an-mau-is-ma-a-leebtoog-noo-ned-untakumman', 'So a Traumpä von an Mau is ma a Leebtoog noo ned untakumman!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So ein Trampel von einem Mann ist mir ein Lebtag noch nicht untergekommen!', '[{"kategorie": "wörtlich", "text": "\"So ein grobschlächtiges Mannsbild ist mir Zeit meines Lebens noch nie untergekommen!\"  2. \"So ein Holzhammertyp ist mir echt noch nie über den Weg gelaufen!\"  3. \"So einem ungehobelten Rüpel bin ich noch nie begegnet!"}]'::jsonb, ''),
  ('seit-dea-bauantraumpae-do-seaviad-schaeaewads-olle-zeen-minuutn-iagendwo-im-lokal', 'Seit dea Bauantraumpä do seaviad, schääwads olle zeen Minuutn iagendwo im Lokal!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Seit dieser Bauerntrampel da serviert, scheppert''s alle zehn Minuten irgendwo im Lokal!', '[{"kategorie": "wörtlich", "text": "\"Seit dieses Trampeltier vom Land hier serviert, fliegt ständig irgendwas durch die Gegend!\"  2. Seit diese Abrissbirne vom Land hier serviert, geht im Lokal ständig was zu Bruch!  3. Seit diese Dumpfbacke vom Land hier serviert, überleben die Gläser nur noch ein paar Stunden!"}]'::jsonb, ''),
  ('du-deppada-bauantraumpae-gee-haam-und-tua-kia-moeoekn', 'Du deppada Bauantraumpä! Gee haam und tua Kia möökn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du depperter Bauerntrampel! Geh heim und tu Kühe melken!', '[{"kategorie": "wörtlich", "text": "\"Du blöde Landpomeranze - geh zurück in die Provinz und melke lieber die Kühe!\"  2. Du Bauernweib ohne jedes Feingefühl - geh zurück in die Provinz Schafe hüten!\"  3. Du Dumpfbacke vom Land - geh zurück auf deinen Bauernhof und sperr dich im Kuhstall ein!"}]'::jsonb, ''),
  ('a-so-a-blaeaede-gaass', 'A so a blääde Gaass!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Eine so eine blöde Ziege', '[{"kategorie": "wörtlich", "text": "\"Was für eine blöde Ziege!\"  2. \"Was für ein deppertes Frauenzimmer!\"  3. Was für ein vertrotteltes Weib!"}]'::jsonb, ''),
  ('zua-fettwuaz-soong-de-leit-aa-huatbluuman-waeu-de-blia-wiara-a-klaans-hiatl-auf-de-dickn-blaadln-sitzd', 'Zua Fettwuaz soong de Leit aa ''Huatbluuman'', wäu de Blia wiara a klaans Hiatl auf de dickn Blaadln sitzd!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Zur Fettwurz sagen die Leute auch ''Hutblume'', weil ihre Blüte wie ein kleines Hütchen auf den dicken Blättern sitzt!', '[{"kategorie": "wörtlich", "text": "\"Die Fettwurz wird im Volksmund auch Hutblume genannt, weil ihre Blüte wie ein kleines Hütchen auf den fleischigen Blättern steht!\"  2. Manch einer nannte die Pinguicula vulgaris auch Hutblume, weil ihre zarte Blüte wie ein kleines Hütchen über den breiten, glänzenden Blättern zu schweben scheint!  3. Die Hutblume, im Kräuterlatein ‚pinguicula vulgaris‘, soll ihren Volksnamen daher haben, dass Wanderer ihre dickfleischigen Blätter als kühlendes ‚Hutkraut‘ gegen Sonnenbrand unter die Krempe gelegt haben!"}]'::jsonb, ''),
  ('de-oide-huatbluuman-is-scho-leicht-aus-da-zeit-gfoin', 'De oide Huatbluuman is scho leicht aus da Zeit gfoin!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die alte Hutblume ist schon leicht aus der Zeit gefallen!', '[{"kategorie": "wörtlich", "text": "\"Die alte Hutblume schaut aus, als wär sie aus einem alten Wiener Postkartenständer gefallen!\"  2. \"Die graue Gretl sieht aus, als wär sie aus einer Zeitkapsel geplumpst!\"  3. Die altbackene Matrone sieht aus, als wär sie einem Foto aus dem vorigen Jahrhundert entsprungen – dort wär sie besser auch geblieben!"}]'::jsonb, ''),
  ('graue-greedl', 'graue Greedl', '', '', '', 'Wiener Sprüche, die sitzen!', 'graue Gretl', '[{"kategorie": "wörtlich", "text": "\"angejahrtes Frauchen\""}, {"kategorie": "", "text": "\"altbackene Matrone\""}, {"kategorie": "", "text": "\"welke Hutblume\""}, {"kategorie": "", "text": "[[oide Trutschn]]"}]'::jsonb, ''),
  ('de-graue-greedl-schaud-aus-ois-haedads-wea-aus-an-album-aussegschniidn', 'De graue Greedl schaud aus, ois hädads wea aus an Album aussegschniidn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die alte Hutblume schaut aus, als hätte sie jemand aus einem Album ausgeschnitten!', '[{"kategorie": "wörtlich", "text": "\"Die alte Hutblume schaut aus, als wär sie aus einem alten Wiener Postkartenständer gefallen!\"  2. \"Die altbackene Matrone sieht aus, als wär sie aus einer Zeitkapsel geplumpst!\"  3. Die alte Hutblume sieht aus, als wär sie einem Foto aus dem vorigen Jahrhundert entsprungen – dort wär sie besser auch geblieben!"}]'::jsonb, ''),
  ('bei-dera-huatbluuman-dauads-bis-da-schuellinmg-foid-foisa-iwahaupt-foid', 'Bei dera Huatbluuman dauads, bis da Schüllinmg foid - foisa iwahaupt foid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei der Hutblume dauert’s, bis der Schilling fällt – falls er überhaupt fällt!', '[{"kategorie": "wörtlich", "text": "\"Bei der Hutblume dauert’s, bis der Groschen fällt – wenn er überhaupt fällt!\"  2. Bis die Dumpfbacke was kapiert, ist der Tag auch schon wieder vorbei!  3. \"Dieses Naivchen kriegt überhaupt nichts mit!\""}]'::jsonb, ''),
  ('du-vawoeoekde-huatbluuman-du', 'Du vawöökde Huatbluuman, du!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du verwelkte Hutblume, du!', '[{"kategorie": "wörtlich", "text": "\"Du verblühte Blumenhutmamsell, du!\"  2. (fig.) \"Du altbackene Matrone, du!\"  3. Du alte Jungfer, du!"}]'::jsonb, ''),
  ('des-gaunze-voik-is-zu-aana-kanaeulje-vakumman-de-ian-eiganan-keenich-fiara-schdickl-brood-varoodn-daed', 'Des gaunze Voik is zu aana Kanäulje vakumman, de ian eiganan Keenich fiara Schdickl Brood varoodn däd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Das ganze Volk ist zu einer Kanaille verkommen, dir ihren eigenen König für ein Stück Brot verraten täte!', '[{"kategorie": "wörtlich, hist.", "text": "\"Das ganze Volk ist zu einem Lumpengesindel verkommen, das seinen eigenen König für ein Stück Brot verraten würde!\"  2. Das ganze Volk ist zu einem Schurkenhaufen verkommen - es  würde den eigenen König für ein paar Krümel Brot verkaufen!  3. Das ganze Volkspack ist zu einem treulosen Haufen geworden, der den König für einen Bissen versetzen würde!"}]'::jsonb, ''),
  ('fraunz-haassd-de-kanaeulje', 'Fraunz haassd de Kanäulje!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Franz heißt die Kanaille!', '[{"kategorie": "wörtlich", "text": "\"Franz heißt die miese Type!\"  2. \"Franz heißt die linke Ratte!\"  3. \"Franz heißt das verkommene Subjekt!\""}]'::jsonb, ''),
  ('sei-oide-is-a-goeoedgiirige-kanaeulje-de-ziagd-eam-an-jeedn-cent-aus-da-toschn', 'Sei Oide is a göödgiirige Kanäulje - de ziagd eam an jeedn Cent aus da Toschn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seine Alte ist eine geldgierige Kanaille - die zieht ihm jeden Cent aus der Tasche!', '[{"kategorie": "wörtlich", "text": "\"Seine Frau ist ein geldgieriges, liederliches Weibsstück - zieht ihm jeden Cent aus der Tasche!\"  2. Seine Alte ist eine geldgierige, verkommene Kreatur - sie nimmt ihn bis auf den letzten Cent aus!  3. Seine Alte ist eine geldgierige Bitch – sie zieht ihm alles aus der Tasche, was geht!"}]'::jsonb, ''),
  ('du-goeoedgiirige-kanaeulje', 'Du göödgiirige Kanäulje!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du geldgierige Kanaille!', '[{"kategorie": "wörtlich", "text": "\"Du geldgierige Ratte!\"  2. \"Du verkommene, geldgierige Kreatur!\"  3. (in Bezug auf Frauen): \"Du geldgieriges, liederliches Weibsstück!\""}]'::jsonb, ''),
  ('de-neiche-koeoenarin-is-a-laamoaschade-laundpomaranzn-schdeed-do-wia-frisch-vom-traktoa-gfoin', 'De neiche Köönarin is a laamoaschade Laundpomaranzn - schdeed do wia frisch vom Traktoa gfoin!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die neue Kellnerin ist eine lahmarschige Landpomeranze - steht da, wie frisch vom Traktor gefallen!', '[{"kategorie": "wörtlich", "text": "\"Die neue Kellnerin ist ein behäbiges Landei - steht da, wie frisch vom Traktor gefallen!\"  2. \"Die neue Kellnerin ist ein arbeitsfaules Landküken - steht da wie s''verschlafene Dorfmariechen!\"  3. Die neue Kellnerin ist ''ne echte Provinzschnecke – steht rum, als hätt sie die Zapfanlage zum ersten Mal gesehen!"}]'::jsonb, ''),
  ('de-laundpomarantschn-is-so-laungsaum-im-schaeaedl-de-meakd-ned-amoi-waunnsd-ia-de-kassa-untan-oasch-wegzaasd', 'De Laundpomarantschn is so laungsaum im Schäädl - de meakd ned amoi, waunnsd ia de Kassa untan Oasch wegzaasd!', '', '', '', 'Wiener Gaunersprache', 'Die Landpomerantsche ist so langsam im Schädel - die merkt nicht einmal, wenn du ihr die Kasse unterm Arsch wegziehst!', '[{"kategorie": "wörtlich", "text": "\"Dieses Landküken ist so langsam im Kopf - die merkt’s nicht mal, wenn du ihr die Kasse unterm Hintern wegziehst!\"  2. Das naive Landei ist dermaßen neben der Spur - die kriegt nicht mal mit, wenn du mit der Kassa aus dem Laden marschierst!  3. Dieser Bauerntrampel checkt gar nichts - die bemerkt nicht mal, wenn das Geld unterm Tresen verschwindet!"}]'::jsonb, ''),
  ('da-oide-schroong-im-schuppn-is-echt-zaach-dea-troogd-no-imma-a-jeeds-hoizschdickl', 'Da oide Schroong im Schuppn is echt zaach - dea troogd no imma a jeeds Hoizschdickl!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der alte Schragen im Schuppen ist zäh - der trägt noch immer ein jedes Holzstückl!', '[{"kategorie": "wörtlich", "text": "\"Der alte Sägebock im Schuppen ist richtig robust - der trägt noch immer jedes Stück Holz!\"  2. Das alte Holzgestell da im Schuppen ist erstaunlich stabil –  das hält bombenfest, egal was du drauflegst!  3. Der alte Bock im Schuppen ist widerstandsfähig wie eh und je – jedes Stück Holz schafft er!"}]'::jsonb, ''),
  ('da-oide-schroong-im-gaestezimma-schaeaewad-schoo-waunnsd-di-nua-draufsetzd', 'Da oide Schroong im Gästezimma schääwad schoo, waunnsd di nua draufsetzd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der alte Schragen im Gästezimmer scheppert schon, wenn du dich nur draufsetzt!', '[{"kategorie": "wörtlich", "text": "\"Das alte Bettgestell im Gästezimmer klappert schon, sobald man sich draufsetzt!\"  2. Der alte Bettrahmen im Gästezimmer knarrt bei jeder Bewegung!  3. Bei jeder kleinen Gewichtsverlagerung quietscht das alte Bett im Gästezimmer!"}]'::jsonb, ''),
  ('waunn-dea-schroong-bei-dia-vuabeigeed-schaeaewads-und-du-glaubsd-dea-foid-glei-ausaranaunda', 'Waunn dea Schroong bei dia vuabeigeed, schääwads - und du glaubsd, dea foid glei ausaranaunda!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn der Schragen bei dir vorbeigeht, scheppert''s - und du glaubst, der fällt gleich auseinander!', '[{"kategorie": "wörtlich", "text": "\"Wenn dieses Wackelgestell auf zwei Beinen bei dir vorbeigeht, scheppert''s - und du glaubst, der fällt gleich auseinander!\"  2. Wenn dieses klapprige Zweibein-Gestell bei dir vorbeigeht, scheppert alles – und man denkt, es zerfällt im Gehen!  3. Wenn dieses scheppernde Laufgestell vorbeikommt, klingt’s, als ob’s beim nächsten Schritt auseinanderfällt!"}]'::jsonb, ''),
  ('da-oide-schroong-aun-da-schaunk-richt-ollas-aus-wos-si-beweegd', 'Da oide Schroong aun da Schaunk richt ollas aus, wos si beweegd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der alte Schragen an der Schank richtet alles aus, was sich bewegt!', '[{"kategorie": "wörtlich", "text": "\"Die dürre Alte an der Schank richtet alles aus, was sich bewegt!\"  2. Die alte, knorrige Schankhexe zieht über alles und jeden her, der sich rührt!  3. Die dürre, alte Schankkellnerin lässt keinen gehen, ohne ihm ein böses Wort hinterherzuwerfen!"}]'::jsonb, ''),
  ('du-schiacha-oida-schroong', 'Du schiacha, oida Schroong!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du schircher, alter Schragen!', '[{"kategorie": "wörtlich", "text": "\"Du hässliches, altes Wackelgestell auf zwei Beinen!\"  2. \"Du hässliches, dürres, altes Weib!\"  3. \"Du unansehnliche, alte Schachtel!\""}]'::jsonb, ''),
  ('aum-schroong-liing', 'aum Schroong liing', '', '', '', 'Tod und Sterben auf Wienerisch', 'auf dem Schragen liegen', '[{"kategorie": "wörtlich", "text": "\"auf der Totenbahre liegen\""}, {"kategorie": "", "text": "\"zur letzten Ruhe gebettet sein\""}, {"kategorie": "", "text": "\"im Trauerhaus aufgebahrt sein\""}]'::jsonb, 'Da Koarl hod si gestan in Oasch auskeegld - jetzd liigd ar aum Schroong!'),
  ('da-koarl-hod-si-gestan-in-oasch-auskeegld-jetzd-liigd-ar-aum-schroong', 'Da Koarl hod si gestan in Oasch auskeegld - jetzd liigd ar aum Schroong!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Karl hat sich den Arsch ausgekegelt - jetzt liegt er auf dem Schragen!', '[{"kategorie": "wörtlich", "text": "\"Der Karl hat gestern das Zeitliche gesegnet - jetzt liegt er auf der Totenbahre!\"  2. Der Karl ist gestern verstorben – jetzt ist er zur letzten Ruhe gebettet!  3. Der Karl hat gestern den Löffel abgegeben - jetzt ist er im Trauerhaus aufgebahrt!"}]'::jsonb, 'aum Schroong liing'),
  ('da-oide-kreidaschroong-kummd-a-jeeds-wochnend-ins-wiatshaus-und-wueue-uns-iare-neichastn-wundamittln-audraan', 'Da oide Kreidaschroong kummd a jeeds Wochnend ins Wiatshaus und wüü uns iare neichastn Wundamittln audraan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der alte Kräuterschragen kommt jedes Wochenende ins Wirtshaus und will uns ihre neuesten Wundermittel andrehen!', '[{"kategorie": "wörtlich", "text": "\"Die alte Kräuterhexe kommt jedes Wochenende ins Wirtshaus und will uns ihre neuesten Wundermittel aufschwatzen!\"  2. Die Kräuterfrau vom Wald kommt jeden Samstag runter ins Beisl und will uns ihre neuesten Wundermittel verkaufen!  3. Dieser alte Kräuterdrache steht jedes Wochenende bei uns im Wirtshaus und preist ihre neuesten Mixturen an!"}]'::jsonb, ''),
  ('da-klaadaschroong-woa-so-voi-dass-d-wiatshaustia-nimma-gaunz-aufgaunga-is', 'Da Klaadaschroong woa so voi, dass d''Wiatshaustia nimma gaunz aufgaunga is!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Kleiderschragen war so voll, dass die Wirtshaustüre nicht mehr ganz aufgegangen ist!', '[{"kategorie": "wörtlich", "text": "\"Der Garderobenbaum war so vollgehängt, dass die Wirtshaustüre nicht mehr ganz aufgegangen ist!\"  2. Der Garderobenständer war so zugepflastert, dass man bei der Wirtshaustür kaum noch reingekommen ist!  3. Am Garderobenbaum hing ein derartiger Berg von Jacken, dass sich die Wirtshaustür nur noch einen Spaltbreit öffnen ließ!"}]'::jsonb, ''),
  ('waunnsd-den-klaadaschroong-z-hoat-puudasd-foida-da-ausaranaunda', 'Waunnsd den Klaadaschroong z''hoat puudasd, foida da ausaranaunda!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn du den Kleiderschragen zu hart puderst, fällt er dir auseinander!', '[{"kategorie": "wörtlich", "text": "\"Wenn du dieses Klappergestell zu hart bumst, fällt es auseinander!\"  2. Wenn du dieses Wackelgestell auf zwei Beinen beim Sex zu hart hernimmst, fällt es auseinander!  3. Dieses Heugeigengestell darfst du nicht zu hart vögeln, sonst fällt''s dir auseinander!"}]'::jsonb, ''),
  ('ausaranaunda-mit-eich', 'Ausaranaunda mit eich!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Auseinander mit euch!', '[{"kategorie": "wörtlich", "text": "\"Geht auseinander!\"  2. \"Beide einen Schritt zurück!\"  3. \"Lasst sofort ab voneinander!\"  4. \"Schluss jetzt, jeder geht in seine Ecke!"}]'::jsonb, ''),
  ('schau-ma-hoit-ind-schbeiskoatn-iagendwos-weama-schoo-findn-wos-uns-ned-glei-umbringd', 'Schau ma hoit ind Schbeiskoatn - iagendwos weama schoo findn, wos uns ned glei umbringd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Schauen wir halt in die Speisekarte - irgendwas werden wir schon finden, was uns nicht gleich umbringt!', '[{"kategorie": "wörtlich", "text": "\"Na gut, schauen wir halt in die Karte – irgendwas wird schon dabei sein, das uns nicht gleich umhaut!\"  2. Werfen wir halt einen Blick in die Speisenliste – vielleicht gibt’s was, das uns überleben lässt!  3. Gut, schauen wir rein in die Karte – vielleicht steht ja irgendwas Essbares drin, das uns nicht gleich den Magen sprengt!"}]'::jsonb, ''),
  ('da-feardl-hod-a-schbeiskoatn-de-reicht-von-aana-aafochn-kralowaad-iwan-schraunkla-bis-zua-keandhockn', 'Da Feardl hod a Schbeiskoatn, de reicht von aana aafochn Kralowaad iwan Schraunkla bis zua Keandhockn!', '', '', '', 'Wiener Gaunersprache', 'Der Ferdl hat eine Speisekarte, die reicht von ''ner einfachen Kralowad über ''nen Schrankler bis zur Körnerhacken!', '[{"kategorie": "wörtlich", "text": "\"Der Ferdinand hat ein Vorstrafenregister, das reicht vom einfachen Bruch übers Safeknacken bis hin zum Juwelendiebstahl!\"  2. Der Ferdi bringt ’ne Akte mit, da steht alles drauf – angefangen beim einfachen Einbruch übers Schlösserknacken bis hin zum Juwelenraub!  3. Ferdinands Vorstrafenliste ist länger als ein Bauchladen – vom einfachen Einbruch über Safenacken bis hin zum ganz großen Juwelendiebstahl!"}]'::jsonb, ''),
  ('de-oide-schbinoodwochtl-sitzd-in-gaunzn-toog-aum-fensta-und-schimpfd-an-jeedn-dea-untn-bei-ia-vuabeimaschiad', 'De oide Schbinoodwochtl sitzd in gaunzn Toog aum Fensta und schimpfd an jeedn, dea untn bei ia vuabeimaschiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die alte Spinatwachtel sitzt den ganzen Tag am Fenster und schimpft jeden, der unten bei ihr vorbeimarschiert!', '[{"kategorie": "wörtlich", "text": "\"Die alte Schrulle hockt den ganzen Tag am Fenster und fährt jeden an, der unten bei ihr vorbeitrabt!\"  2. Die alte Schreckschraube hockt wie ein Wachhund am Fenster und schimpft jeden, der unten am Gehsteig bei ihr vorbeigeht!  3. Die spinnerte alte Matrone thront oben am Fensterbrett und beschimpft alles, was sich unten am Gehsteig bewegt!"}]'::jsonb, ''),
  ('du-deppade-oide-schbninoodwochtl', 'Du deppade, oide Schbninoodwochtl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du depperte, alte Spinatwachtel!', '[{"kategorie": "wörtlich", "text": "\"Du spinnerte alte Schreckschraube!\"  2. \"Du durchgeknallte alte Matrone!\"  3. \"Du geistig umnachtete, alte Schrulle!\""}]'::jsonb, ''),
  ('de-schbinoodwochta-san-vua-da-linienhittn-gschdaundn-und-haum-de-fuaweak-kontroliiad-de-in-de-schdodt-woitn', 'De Schbinoodwochta san vua da Linienhittn gschdaundn und haum de Fuaweak kontroliiad, de in de Schdodt woitn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Spinatwachter sind jeden Tag vor der Linienhütte gestanden und haben die Fuhrwerke kontrolliert, die in die Stadt wollten!', '[{"kategorie": "wörtlich", "text": "\"Die grün uniformierten Grenzwächter standen vor ihren Hütten am [[Linienwall]] und haben die Fuhrwerke kontrolliert, die in die Stadt wollten!\"  2. Die grün gewandeten Linienwächter standen an den Hütten des Linienwalls und nahmen die Fuhrwerke unter die Lupe, die in die Stadt wollten!  3. Vor den kleinen Linienhütten standen die grün uniformierten Wächter der Stadtlinie und hielten die einfahrenden Wagen an, die in Richtung Stadt rollten!"}]'::jsonb, ''),
  ('de-schbinoodwochta-haum-a-lauschal-auf-ollas-de-hean-sogoa-de-fliang-hupfn', 'De Schbinoodwochta haum a Lauschal auf ollas - de hean sogoa de Fliang hupfn!', '', '', '', 'Wiener Gaunersprache', 'Die Spinatwachter haben ein Lauscherl auf alles – die hören sogar die Fliegen hüpfen!', '[{"kategorie": "wörtlich", "text": "\"Die Grün-Uniformierten haben Ohren wie Luchse – denen entgeht kein einziger Mucks!\"  2. Die Wachmänner haben ihre Lauscher auf Anschlag – die hören sogar deinen Schatten husten!  3. Die Polizisten haben ihre Ohren gespitzt wie Jagdhunde – die fangen jeden Atemzug sein!"}]'::jsonb, 'a Lauschal auf ollas haum'),
  ('a-lauschal-auf-ollas-haum', 'a Lauschal auf ollas haum', '', '', '', 'Wiener Gaunersprache', 'ein Lauscherl auf alles haben', '[{"kategorie": "wörtlich", "text": "\"die Lauscher ständig auf Empfang haben\""}, {"kategorie": "", "text": "\"die Ohren überall haben\""}, {"kategorie": "", "text": "\"die Antennen auf alles ausgefahren haben\""}]'::jsonb, ''),
  ('hoid-de-goschn-du-trudschn-du-reedsd-jo-mea-schmoan-ois-a-bsoffana-papagei', 'Hoid de Goschn, du Trudschn - du reedsd jo mea Schmoan ois a bsoffana Papagei!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Halt die Goschen, du Trutschen - du redest ja mehr Schmarren als ein besoffener Papagei!', '[{"kategorie": "wörtlich", "text": "\"Halt die Klappe, du dämliches Frauenzimmer - du quatscht ja mehr Unsinn als ein besoffener Papagei!\"   2. Halt die Pappen, du blöde Tratschtrommel - du haust ja mehr Blödsinn raus als ein besoffener Papagei!  3. Schnauze, du Krawallweib - dein blödes Geschwätz ist nicht mehr auszuhalten!"}]'::jsonb, ''),
  ('des-trudschal-von-aana-koeoenarin-wueue-uns-gschdaundanan-maunan-dazoeoen-wia-de-woeoed-funktioniad-do-duckt-si-da-gaunze-schdaummtisch-weg', 'Des Trudschal von aana Köönarin wüü uns gschdaundanan Maunan dazöön, wia de Wööd funktioniad - do duckt si da gaunze Schdaummtisch weg!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Das kleine Trutscherl von einer Kellnerin will uns gestandenen Männern erzählen, wie die Welt funktioniert - da duckt sich der ganze Stammtisch weg!', '[{"kategorie": "wörtlich", "text": "\"Die dumme Kellnertussi glaubt ernsthaft, uns alten Haudegen erklären zu können, wie die Welt rennt – da versinkt der ganze Stammtisch im Bierglas!\"  2. Das dümmliche Mädel hinter der Schank will uns gestandenen Männern das Leben erklären - da kannst den Bierkrug nur noch wie ''nen Schutzschilder hochhalten!   3. Das dämliche Kellnermädel spielt sich als Besserwisserin vor uns alten Säcken auf – da flüchtet sogar der Wirt in den Keller!"}]'::jsonb, ''),
  ('troogd-de-faesche-kotz-wos-untrisch', 'Troogd de fäsche Kotz wos untrisch?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Trägt die fesche Katz was untrisch?', '[{"kategorie": "wörtlich", "text": "\"Hat das fesche Mädel darunter auch noch was an?\"  2. \"Trägt das fesche Mädel drunter Unterwäsche oder nicht?\"  3. \"Hat die fesche Katz unter der Montur noch ein Schichterl versteckt?\""}]'::jsonb, ''),
  ('troogd-de-faesche-kotz-wos-untarisch', 'Troogd de fäsche Kotz wos untarisch?', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Trägt die fesche Katz was untarisch?', '[{"kategorie": "wörtlich", "text": "\"Hat das fesche Mädel darunter auch noch was an?\"  2. \"Trägt das fesche Mädel drunter Unterwäsche oder nicht?\"  3. \"Hat die fesche Katz unter der Montur noch ein Schichterl versteckt?\""}]'::jsonb, ''),
  ('und-hintn-nooch-reit-de-oide-uaschl', 'Und hintn nooch reit de oide Uaschl!', '', '', '', 'Echte Wiener Schmähperlen', 'Und hinten nach reitet die alte Urschel!', '[{"kategorie": "wörtlich", "text": "\"Und hinten nach kommt die dämliche Alte geritten!\"  2. (fig., scherzhaft für): \"Im Nachhinein ist man immer klüger!\"  3. \"Hinterher sind alle g’scheit!\"  4. \"Und zum Schluss kommt wie immer die alte Weisheit angeritten!\""}]'::jsonb, ''),
  ('du-blaeaede-uaschl', 'Du blääde Uaschl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du blöde Urschel!', '[{"kategorie": "wörtlich", "text": "\"Du dämliches Frauenzimmer!\"  2. \"Du hirnvernebeltes Weibsstück!\"  3. \"Du blöde [[Schnepfen]]!\"  4. \"Du depperte [[Funsen]]!\""}]'::jsonb, ''),
  ('du-schiache-uaschl', 'Du schiache Uaschl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du schirche Urschel!', '[{"kategorie": "wörtlich", "text": "\"Du hässliches Weib!\"  2. \"Du unansehnliches Frauenzimmer!\"  3. \"Du grässliche Vettel!\"  4. [[Du schiache Göösn!]]  5. [[Du schiache Grammä!]]  6. [[Du schiache Gaass!]]"}]'::jsonb, 'Du schiache Göösn!'),
  ('du-schiache-goeoesn', 'Du schiache Göösn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du schirche Gelse!', '[{"kategorie": "wörtlich", "text": "\"Du hässliches Lästerweib!\"  2. \"Du unansehnliches, lästerndes Frauenzimmer!\"  3. \"Du grässliche, nervige Vettel!\"  4. [[Du schiache Uaschl!]]  5. [[Du schiache Grammä!]]  6. [[Du schiache Gaass!]]"}]'::jsonb, 'Du schiache Uaschl!'),
  ('du-schiache-grammae', 'Du schiache Grammä!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du schirche Urschel!', '[{"kategorie": "wörtlich", "text": "\"Du hässliches Weib!\"  2. \"Du unansehnliches Frauenzimmer!\"  3. \"Du grässliche Vettel!\"  4. [[Du schiache Göösn!]]  5. [[Du schiache Uaschl!]]  6. [[Du schiache Gaass!]]"}]'::jsonb, 'Du schiache Uaschl!'),
  ('du-schiache-gaass', 'Du schiache Gaass!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du schirche Geiß!', '[{"kategorie": "wörtlich", "text": "\"Du hässliche Ziege!\"  2. \"Du unansehnliches Frauenzimmer!\"  3. \"Du grässliche Vettel!\"  4. [[Du schiache Göösn!]]  5. [[Du schiache Grammä!]]  6. [[Du schiache Uaschl!]]"}]'::jsonb, 'Du schiache Uaschl!'),
  ('so-wiasd-ned-oid-so-darennsd-di-boid', 'So wiasd ned oid - so darennsd di boid!', '', '', '', 'Tod und Sterben auf Wienerisch', 'So wirst du nicht alt - so wirst du dich bald derrennen!', '[{"kategorie": "wörtlich", "text": "\"So wirst du nicht alt - so wirst du bald das Zeitliche segnen!\"  2. \"So machst du''s nicht mehr lange - so wirst du bald ins Gras beißen!\"  3. \"So bringst du dich selber schneller um die Kurve, als dir lieb ist!\""}]'::jsonb, ''),
  ('zu-oim-wos-im-reindl-picknbleibd-soogd-de-oma-urass', 'Zu oim, wos im Reindl picknbleibd, soogd de Oma ''Urass''!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Zu allem, was im Reindl pickenbleibt, sagt die Oma ''Urass''!', '[{"kategorie": "wörtlich", "text": "\"Alles, was im Topf pickenbleibt, nennt die Oma ''Urass''!\"  2. Sämtliche Topfreste nennt die Oma schlicht ''Urass''!  3. Was im Topf zurückbleibt, gilt bei der Oma als ''Urass'' - verschwendetes Essen!"}]'::jsonb, ''),
  ('an-urass-mit-wos-treibm', 'an Urass mit wos treibm', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Urass mit etwas treiben', '[{"kategorie": "wörtlich", "text": "\"Raubbau mit etwas treiben\""}, {"kategorie": "", "text": "\"verschwenderisch mit etwas umgehen\""}, {"kategorie": "", "text": "\"etwas ohne Maß und Ziel verprassen\""}]'::jsonb, ''),
  ('ia-treibds-an-urass-min-essn-ois-warads-nix-weat-und-follad-vom-himmae', 'Ia treibds an Urass min Essn - ois warads nix weat und follad vom Himmä!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ihr treibt einen Urass mit dem Essen - als wäre es nichts wert und würde vom Himmel fallen!', '[{"kategorie": "wörtlich", "text": "\"Ihr vergeudet das Essen, als wär’s wertlos und im Überfluss da!\"  2. Ihr geht mit dem Essen um, als wär’s Abfall und würde nichts kosten!  3. Ihr verschleudert das Essen, als tät''s der Herrgott sowieso jeden Tag gratis nachliefern!"}]'::jsonb, 'an Urass mit wos treibm'),
  ('i-urass-liawa-ois-dass-i-schboa-auf-a-scheene-leich', 'I urass liawa ois dass I schboa auf a scheene Leich!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich urasse lieber, als dass ich spar auf eine schöne Leich!', '[{"kategorie": "wörtlich", "text": "\"Ich schlage lieber über die Stränge, als dass ich auf ein teures Begräbnis spare!\"  2. \"Ich werfe lieber mit dem Geld um mich, als dass ich es auf einem teuren Begräbnis vergrab!\"  3. Ich genieße lieber das Leben, statt mein Geld für ein pompöses Begräbnis aufzusparen!"}]'::jsonb, ''),
  ('de-urassn-ois-obs-an-goeoedscheissa-dahaam-haedn', 'De urassn, ois obs an Göödscheissa dahaam hädn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die urassen, als ob sie einen Geldscheißer daheim hätten!', '[{"kategorie": "wörtlich", "text": "\"Die verprassen alles, als ob sie einen Geldscheißer daheim hätten!\"  2. \"Die hauen das Geld raus, als würd’s am Baum wachsen!\"  3. \"Die verbraten die [[Marie]], als ob’s aus dem Brunnen nachfließt!\""}]'::jsonb, ''),
  ('tuads-ned-urassn', 'Tuads ned urassn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Tut nicht urassen!', '[{"kategorie": "wörtlich", "text": "\"Seid nicht so verschwenderisch!\"  2. \"Geht sparsam damit um!\"  3. \"Hört auf, alles sinnlos zu vergeuden!\""}]'::jsonb, ''),
  ('a-essn-schdeelossn-is-ned-nua-urassich-sondan-a-unheeflich-geengiwa-da-kechin', 'A Essn schdeelossn, is ned nua urassich, sondan a unheeflich geengiwa da Kechin!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Essen überlassen, ist nicht nur urassig, sondern auch unhöflich gegenüber der Köchin!', '[{"kategorie": "wörtlich", "text": "\"Eine Mahlzeit überzulassen, ist nicht nur verschwenderisch, sondern auch unhöflich gegenüber der Köchin!\"  2. Essen liegenzulassen ist nicht nur Verschwendung, sondern auch echt respektlos gegenüber der Köchin!  3. Eine Mahlzeit unangerührt zurückzulassen ist nicht nur Verschwendung hoch zehn, sondern auch richtig mies der Köchin gegenüber!"}]'::jsonb, ''),
  ('wos-fiara-keeplade-hianvaneebede-uaschl', 'Wos fiara keeplade, hianvaneebede Uaschl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Was für eine keppelnde, hirnvernebelte Urschel!', '[{"kategorie": "wörtlich", "text": "\"Was für ein keifendes, blödes Frauenzimmer!\"  2. \"Was für ein kreischendes, vertrotteltes Weib!\"  3. \"Was für ''ne blöde, meckernde Ziege!\""}]'::jsonb, ''),
  ('de-weedahex-is-zsaummgfoitn-so-klaa-dass-in-jeede-jackntoschn-passd', 'De Weedahex is zsaummgfoitn so klaa, dass in jeede Jackntoschn passd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Wetterhexe ist zusammengefaltet so klein, dass sie in jede Jackentasche passt!', '[{"kategorie": "wörtlich", "text": "\"Der Regenponcho ist so kompakt gefaltet, dass er problemlos in jede Jackentasche passt!\"  2. Im gefalteten Zustand ist die Wetterhexe kaum größer als ein Päckchen Taschentücher!  3. Die zusammengelegte Regenhaut ist so klein, dass sie in jede Jackentasche hineinpasst!"}]'::jsonb, ''),
  ('loss-mi-easchd-moi-de-hoa-richtn-i-schau-jo-aus-wiara-weedahex', 'Loss mi easchd moi de Hoa richtn - I schau jo aus wiara Weedahex!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Lass mich erst mal die Haare richten - ich sehe ja aus wie eine Wetterhexe!', '[{"kategorie": "wörtlich", "text": "\"Lass mich kurz meine Mähne bändigen - ich sehe ja aus, als hätt ich in der Windmaschine geschlafen!\"  2. Warte, bis ich meinen Wuschelkopf gestylt habe - ich schaue ja aus wie die Struwwelliese höchstpersönlich!  3. Warte, ich seh noch komplett zerknautscht und zerzaust aus - muss mir nur schnell die Haare machen!"}]'::jsonb, ''),
  ('oone-reenghaut-waarad-i-do-oobm-aum-beag-voi-oogsoffn', 'Oone Reenghaut waarad I do oobm aum Beag voi oogsoffn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ohne Regenhaut wär ich da oben am Berg voll abgesoffen!', '[{"kategorie": "wörtlich", "text": "\"Ohne den Regenponcho wäre ich da oben auf dem Berg bis auf die Knochen nass geworden!\"  2. Ohne Pelerine wär ich da oben rumgelaufen wie ein tropfender Waschlappen!  3. Gott sei Dank hatte ich die Wetterhexe mit am Berg - sonst wäre ich klatschnass geworden!"}]'::jsonb, ''),
  ('oone-rettungswestn-waarad-i-im-koidn-wossa-oogsoffn', 'Oone Rettungswestn waarad I im koidn Wossa oogsoffn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ohne Rettungsweste wäre ich im kalten Wasser abgesoffen!', '[{"kategorie": "wörtlich", "text": "\"Ohne Rettungsweste wäre ich im kalten Wasser ertrunken!\"  2. \"Das kalte Wasser hätte mich ohne Rettungsweste gnadenlos verschluckt!\"  3. \"Ohne Rettungsweste wäre ich im Eiswasser untergegangen und unauffindbar verschwunden!\""}]'::jsonb, ''),
  ('amoi-zvueue-gaas-beim-schdaatn-und-zack-is-ma-da-bock-komplett-oogsoffn', 'Amoi zvüü Gaas beim Schdaatn - und zack, is ma da Bock komplett oogsoffn!', '', '', '', 'Wiener Mechaniker-Slang', 'Einmal zu viel Gas beim Starten — und zack, ist mir der Bock komplett abgesoffen!', '[{"kategorie": "wörtlich", "text": "\"Kurz übertrieben beim Gas — und der Motor war sofort totgedrückt!\"  2. Zu viel Gas im Kaltstart —und schon schmiert dir die Maschine ab!  3. Ein Gasstoß zu viel, und schon hat’s mir die Mühle komplett zugeschmiert!"}]'::jsonb, ''),
  ('zoodl1', 'Zoodl1', 'die', '', '', 'Grundwortschatz Wienerisch', 'Zottel', '[{"kategorie": "wörtlich", "text": "\"Zottel\" (vom mittelhochdeutschen \"zotel\"=\"herabhängendes Haarbüschel\")"}, {"kategorie": "allg.", "text": "\"lange, fettige Haarsträhne\", \"langes, glattes, schlaff fallendes Haar\", \"herunterhängende Haarsträhne\", \"langes, ungepflegt wirkendes Haar\""}, {"kategorie": "in Bezug auf Frauen", "text": "\"zerzaustes, ungepflegtes Weibsbild\", \"Struwwelkopf\",\"zerrupfte Vogelscheuche\", \"Zauselkopf\", [[Weedahex]]"}, {"kategorie": "Gaunerjargon", "text": "\"Strichmädchen\", \"Hure\", \"Prostituierte\", [[Zuschel]]"}]'::jsonb, 'Noochn Reeng samma de Zoodln oweghhängd wia de nossn Fraunsn von an Wischfetzn!'),
  ('zoodl2', 'Zoodl2', 'der', '', '', 'Grundwortschatz Wienerisch', 'Zottel', '[{"kategorie": "wörtlich", "text": "\"Zottel\" (vom mittelhochdeutschen \"zoten\"=\"bummeln\")"}, {"kategorie": "allg.", "text": "Nachtbummler, Partygänger, Nachtschwärmer, \"Bar-Hopper\""}]'::jsonb, 'Seawas, du oida Zoodl! Imma noo auf Tua?'),
  ('seawas-du-oida-zoodl-imma-noo-auf-tua', 'Seawas, du oida Zoodl! Imma noo auf Tua?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Servus, du alter Zottel! Immer noch auf Tour?', '[{"kategorie": "wörtlich", "text": "\"Servus, du alter Nachtschwärmer! Bist schon wieder auf Tour?\"  2. Na, du Bar-Hopper! Schleichst immer noch durch die Lokale?  3. Hallo, du alte Nachteule! Wieder auf Streifzug durch die Stadt?"}]'::jsonb, ''),
  ('mia-zoodln-von-schaunk-zu-schaunk-wia-zwaa-schdreina-de-eana-reviia-ookloppan', 'Mia zoodln von Schaunk zu Schaunk wia zwaa Schdreina, de eana Reviia ookloppan!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wir zotteln von Schank zu Schank wie zwei Streuner, die ihr Revier abklappern!', '[{"kategorie": "wörtlich", "text": "\"Wir zotteln von Schank zu Schank wie zwei Beislpiraten auf Rundgang!\"  2. Wir ziehen von Bude zu Bude wie zwei Nachtschwärmer auf Patrouille!  3. Wir tingeln von Lokal zu Lokal wie wie zwei nächtliche Reviergänger!"}]'::jsonb, ''),
  ('noochn-reeng-samma-de-zoodln-oweghhaengd-wia-de-nossn-fraunsn-von-an-wischfetzn', 'Noochn Reeng samma de Zoodln oweghhängd wia de nossn Fraunsn von an Wischfetzn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach dem Regen sind mir die Zotteln runtergehängt wie die nassen Fransen von einem Wischfetzen!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Regen hingen mir die Zotteln runter wie nasse Wischmop-Fäden!\"  2. Nach dem Platzregen baumelten meine Haare wie durchweichte Mop-Strähnen an mir runter!  3. Nach dem Wolkenbruch sahen meine Haarsträhnen aus wie die aufgeweichten Tentakel eines Wischmops!"}]'::jsonb, ''),
  ('de-oide-zoodl-hod-an-kraanahoast-aum-schaeaedl', 'De oide Zoodl hod an Kraanahoast aum Schäädl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Diese alte, zerrupfte Vogelscheuche hat einen Krähenhorst am Schädel!', '[{"kategorie": "wörtlich", "text": "\"Diese alte, zerrupfte Vogelscheuche trägt läuft mit einem Krähennest auf dem Kopf herum!\"  2. Diese zerfledderte Alte läuft mit einem halben Vogelnest auf dem Kopf herum!  3. Dieses zerzauste, alte Weibsbild hat ein Haargeflecht am Kopf, als würden zehn streunende Krähen drin wohnen!"}]'::jsonb, ''),
  ('du-zarrupfde-windvabeude-weedahex', 'Du zarrupfde, windvabeude Weedahex!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du zerrupfte, windverbeulte Wetterhexe!', '[{"kategorie": "wörtlich", "text": "\"Du verwitterte, zerzauste Wetterhexe!\"  2. \"Du zerfledderte, sturmverwurschtelte Gewitterhexe!\"  3. Du verfranste, windverbeulte Vogelscheuche!\""}]'::jsonb, ''),
  ('du-windvabeude-zarrupfde-zoodl', 'Du windvabeude, zarrupfde Zoodl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du windverbeulte, zerrupfte Zottel!', '[{"kategorie": "wörtlich", "text": "\"Du verwitterte, zerzauste Wetterhexe!\"  2. \"Du zerfledderte, sturmverwurschtelte Gewitterhexe!\"  3. Du verfranste, windverbeulte Vogelscheuche!\""}]'::jsonb, ''),
  ('waunn-lossda-de-laungan-zoodn-endlich-schneidn-du-schaust-jo-aus-wiara-wischmop-auf-zwa-fiass', 'Waunn lossda de laungan Zoodn endlich schneidn? Du schaust jo aus wiara Wischmop auf zwa Fiass!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wann lässt du dir die langen Zotten endlich schneiden? Du schaust ja aus wie ein Wischmop auf zwei Beinen!', '[{"kategorie": "wörtlich", "text": "\"Kämm dir die langen Zotten durch und lass sie dir endlich schneiden - du siehst aus, als würdest du ein Vogelnest auf deinem Kopf rumtragen!\"  2. Wann stutzt du dir endlich die Mähne? Du siehst ja aus wie ein zerfledderter Zottelgeist!  3. Wann gehst du endlich zum Friseur? Deine Zotten hängen runter wie die Fäden von einem Wischmop!"}]'::jsonb, ''),
  ('nooch-da-duachzechtn-nocht-hob-i-so-zoodad-ausgschaut-ois-haedad-mi-a-schdaubsauga-ausgschbuckd', 'Nooch da duachzechtn Nocht hob I so zoodad ausgschaut, ois hädad mi a Schdaubsauga ausgschbuckd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Nach der durchzechten Nacht hab ich so zottert ausgeschaut, als hätte mich ein Staubsauger ausgespuckt!', '[{"kategorie": "wörtlich", "text": "\"Nach der durchsoffenen Nacht hab ich so zottelig ausgesehen, als hätte mich ein Turbostaubsauger ausgespuckt!\"  2. Nach der durchzechten Nacht war ich so zerzaust, als hätte mich die Müllpresse verschluckt und wieder ausgespuckt!  3. Nach der nächtlichen Lokaltour war ich so zerrupft wie ein zerfledderter Wischmop!"}]'::jsonb, ''),
  ('des-zoowal-hod-a-dichts-seidigs-foeoe-des-eam-vua-da-extreman-koeoedn-in-sibirien-schuetzd', 'Des Zoowal hod a dichts, seidigs Föö, des eam vua da extreman Köödn in Sibirien schützd!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Das Zoberl hat ein dichtes, seidiges Fell, welches das Tier vor der extremen Kälte in Sibirien schützt!', '[{"kategorie": "wörtlich", "text": "\"Der Zobel besitzt ein besonders dichtes, seidiges Fell, das ihn zuverlässig vor der extremen sibirischen Kälte schützt!\"  2. Das dichte, weiche Winterfell des Zobels bietet dem Tier einen hervorragenden Schutz gegen die sibirische Kälte!  3. Das Zoberl trägt ein dichtes, seidig schimmerndes Fell, das optimal an die extremen Winterbedingungen Sibiriens angepasst ist!"}]'::jsonb, ''),
  ('de-kaatl-unsa-wueueds-zoowal-tiigad-heit-wiida-wiara-nochtfoita-duach-de-bars-und-mochd-de-maunda-au', 'De Kaatl, unsa wüüds Zoowal, tiigad heit wiida wiara Nochtfoita duach de Bars und mochd de Maunda au!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Kati, unser wildes Zoberl, tigert heute wieder wie ein Nachtfalter durch die Bars und macht die Männer an!', '[{"kategorie": "wörtlich", "text": "\"Die Kati, unsere wilde Ausgehhexe, tigert heute wieder wie ein Nachtfalter durch die Bars und flirtet sich quer durch die Männerwelt!\"  2. Die Kati, unsere Stadt-Nymphe, tanzt heute wieder durch die Bars und wickelt die Männer reihenweise um den Finger!  3. Die Kati, unser Party-Vulkan, ist heute wieder auf Tour und nimmt die Männerwelt im Sturm – Bar für Bar!"}]'::jsonb, ''),
  ('zuschl1', 'Zuschl1', 'die', '', '', 'Grundwortschatz Wienerisch', 'Zuschel', '[{"kategorie": "wörtlich", "text": "\"Zuschel\" (vom mittelhochdeutschen \"zuschen\"=\"flattern\")"}, {"kategorie": "allg.", "text": "\"zerlumptes Ding\", \"struppige Person\", \"zerrupftes Etwas\", \"zotteriges Wesen\", \"Lumpenbündel\", (in Bezug auf Frauen): \"ungepflegtes Weibsbild\", [[Schlamperl]], [[Zoodl]]"}, {"kategorie": "Gaunerjargon", "text": "\"verlottertes Weibsbild\", \"Dorfmatratze\", \"Wanderpokal\", notorische Fremdgängerin, [[Zoberl]] [[Sandhas]], [[Flitscherl]], [[Schledern]], [[Sumpfzechen]]"}]'::jsonb, 'Dass si dea mit so ana Zuschl iwahaupt unta de Leit traut!'),
  ('zuschl2', 'Zuschl2', 'der', '', '', 'Grundwortschatz Wienerisch', 'Zuschel', '[{"kategorie": "wörtlich", "text": "\"Zuschel\" (vom mittelhochdeutschen \"zuschen\"=\"flattern\")"}, {"kategorie": "allg.", "text": "\"zerlumptes Ding\", \"struppige Person\", \"zerrupftes Etwas\", \"zotteriges Wesen\", \"Lumpenbündel\", liederliche Person, Widerling, [[Ungustl]], [[Gfraassd]]"}, {"kategorie": "Gaunerjargon", "text": "Homosexueller, Schwuler, \"Tunte\", [[Boochana]], [[Ghaazda]], [[Woama]]"}]'::jsonb, 'Aa waunnsd den Zuschl kampäsd und biaschdlsd, kriagst des Bääse ned aus eam ausse!'),
  ('aa-waunnsd-den-zuschl-kampaesd-und-biaschdlsd-kriagst-des-baeaese-ned-aus-eam-ausse', 'Aa waunnsd den Zuschl kampäsd und biaschdlsd, kriagst des Bääse ned aus eam ausse!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Auch wenn du diesen Zuschel kämmst und bürstet, kriegst du das Böse nicht aus ihm raus!', '[{"kategorie": "wörtlich", "text": "\"Selbst wenn du dieses Lumpenbüdel kämmst und bürstet, kriegst du das Böse nicht aus ihm raus!\"  2. Selbst wenn du dieses zotterige Wesen glattscheitelst, bleibt das Biest in ihm wach!  3. Egal wie sehr du dieses zerrupfte Etwas pflegst — das Gfraßt in seinem Inneren bleibt!"}]'::jsonb, ''),
  ('gib-eam-liawa-ned-de-haund-waeu-sunst-schmueuezd-dea-zuschl-weg-wiara-schneemau-im-august', 'Gib eam liawa ned de Haund - wäu sunst schmüüzd dea Zuschl weg wiara Schneemau im August!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Gib ihm lieber nicht die Hand - weil sonst schmilzt dieser Zuschel weg wie ein Schneemann im August!', '[{"kategorie": "wörtlich", "text": "\"Gib ihm lieber nicht die Hand - weil sonst schmilzt diese schwule Tunte weg wie ein Schneemann im August!\"  2. Verzichte lieber auf einen Händedruck mit ihm - denn der Warme zieht dich sonst zu sich runter und küsst dich auf den Mund!  3. Ich würde ihm die Hand lieber nicht geben - denn sonst zefließt dieser Schwule noch vor lauter Männerliebe!"}]'::jsonb, ''),
  ('wia-haum-in-grissbaam-duachn-schnee-zachsld-bis-ma-dahaam-woan', 'Wia haum in Grissbaam duachn Schnee zachsld, bis ma dahaam woan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wir haben den Christbaum durch den Schnee gezachselt, bis wir daheim waren!', '[{"kategorie": "wörtlich", "text": "\"Wir haben den Christbaum durch den Schnee gezogen, bis wir zu Hause waren!\"  2. Wir haben den Weihnachtsbaum durch den Schnee geschleppt, bis wir daheim waren!  3. Wir haben den Cristbaum durch den Schnee geschleift, bis wir völlig erledigt zu Hause angekommen sind!"}]'::jsonb, ''),
  ('da-sepp-hod-uns-olle-heazachsld-und-jetzd-sitz-ma-bei-eam-im-goatn-wia-de-mottn-ums-liacht', 'Da Sepp hod uns olle heazachsld - und jetzd sitz ma bei eam im Goatn wia de Mottn ums Liacht!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Sepp hat uns alle hergezachselt - und jetzt sitzen wir bei ihm im Garten wie die Motten ums Licht!', '[{"kategorie": "wörtlich", "text": "\"Der Sepp hat uns alle hergelotst – und jetzt hocken wir bei ihm im Garten wie die Motten ums Licht!\"  2. Der Sepp hat uns alle hergeschleppt, und jetzt hocken wir bei ihm im Garten wie Mückenschwärme ums Feuer!  3. Der Sepp hat uns hergelockt – und jetzt hängen wir alle in seinem Garten wie Nachtfalter um die Laterne!"}]'::jsonb, ''),
  ('kumm-hea-du-klaana-zausl-i-richt-da-de-hoa', 'Kumm hea, du klaana Zausl, I richt da de Hoa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Komm her, du kleiner Zausel, ich richte dir die Haare!', '[{"kategorie": "wörtlich", "text": "\"Komm her, du kleiner Struwwelkopf, ich mach dir die Haare wieder schön!\"  2. Komm her, du kleine Zottelkugel, ich kümmer mich um deinen Haarschopf!  3. Komm her, du kleiner Wuschel, ich kämme dich schnell durch!"}]'::jsonb, ''),
  ('nau-mei-siass-zausal-host-wiida-min-foeoen-kaempfd', 'Nau, mei siass Zausal - host wiida min Föön kämpfd?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na, mein süßes Zauserl, hast du wieder mit dem Föhn gekämpft?', '[{"kategorie": "wörtlich", "text": "\"Na, mein kleines Struwwelköpfchen, war der Föhn heute wieder stärker als du?\"  2. Na, mein süßes Zottelbärchen - deine Frisur verrät, der Föhn zu stark für dich war!  3. Na, mein kleines Wuschelköpfchen, bist du heute wieder mit dem Föhn aneinandergeraten?"}]'::jsonb, ''),
  ('noochn-pleedara-woa-mei-hund-a-aanzichs-zausichs-foeoekneil', 'Noochn Pleedara woa mei Hund a aanzichs zausichs Föökneil!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Nach dem Plederer war mein Hund ein einziges, zauseliges Fellknäuel!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Regenguss sah mein Hund aus wie ein einziges, zauseliges Fellknäuel!\"  2. Der Regen hat meinen Hund in ein struppiges Fellbüschel verwandelt!  3. Nach dem Regenschauer war mein Hund ein nasses, zotteliges Fellmonsterchen!"}]'::jsonb, ''),
  ('waunn-de-zaeaezn-zum-jaumman-aufaungd-kaunnsd-di-auf-a-oopa-in-drei-aktn-gfossd-mochn', 'Waunn de Zääzn zum Jaumman aufaungd, kaunnsd di auf a Oopa in drei Aktn gfossd mochn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn diese Zezen zu jammern beginnt, kannst du dich auf eine Oper in drei Akten gefasst machen!', '[{"kategorie": "wörtlich", "text": "\"Wenn diese Zimperliese zu jammern beginnt, kannst du dich auf eine Oper in drei Akten gefasst machen!\"  2. Wenn dieses Mimöschen anfängt zu klagen, kannst du Popcorn holen – das dauert länger!  3. Wenn diese Heulsuse loslegt, kannst du dich auf eine private Tragikomödie mit Open-End einstellen!"}]'::jsonb, ''),
  ('waunn-des-zaeaezal-zum-jaumman-aufaungd-kaunnsd-di-auf-a-oopa-in-drei-aktn-gfossd-mochn', 'Waunn des Zääzal zum Jaumman aufaungd, kaunnsd di auf a Oopa in drei Aktn gfossd mochn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn dieses Zezerl zu jammern beginnt, kannst du dich auf eine Oper in drei Akten gefasst machen!', '[{"kategorie": "wörtlich", "text": "\"Wenn dieses Zimperlieschen zu jammern beginnt, kannst du dich auf eine Oper in drei Akten gefasst machen!\"  2. Wenn dieses Mimöschen anfängt zu klagen, kannst du Popcorn holen – das dauert länger!  3. Wenn diese Heulsuse loslegt, kannst du dich auf eine private Tragikomödie mit Open-End einstellen!"}]'::jsonb, ''),
  ('wia-kau-ma-nua-so-zaeaezich-sei-und-weng-an-jeedn-schaas-zum-haeun-aufaungan', 'Wia kau ma nua so zääzich sei und weng an jeedn Schaas zum Häun aufaungan?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie kann man nur so zäzig sein und wegen jedem Schas zu heulen anfangen?', '[{"kategorie": "wörtlich", "text": "\"Wie kann man nur so wehleidig sein und wegen jeder Kleinigkeit heulen?\"  2. Wie kann man nur so larmoyant sein und wegen jedem Furz heulen?  3. Wieso reagierst du immer so mimosenhaft und bist bei jeder Kleinigkeit den Tränen nahe?"}]'::jsonb, ''),
  ('wia-kau-ma-nua-so-zaeaezad-sei-und-weng-an-jeedn-schaas-zum-haeun-aufaungan', 'Wia kau ma nua so zääzad sei und weng an jeedn Schaas zum Häun aufaungan?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie kann man nur so zäzert sein und wegen jedem Schas zu heulen anfangen?', '[{"kategorie": "wörtlich", "text": "\"Wie kann man nur so wehleidig sein und wegen jeder Kleinigkeit heulen?\"  2. Wie kann man nur so larmoyant sein und wegen jedem Furz heulen?  3. Wieso reagierst du immer so mimosenhaft und bist bei jeder Kleinigkeit den Tränen nahe?"}]'::jsonb, ''),
  ('a-haagliche-zaeaezn', 'a haagliche Zääzn', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine hagliche Zäzen', '[{"kategorie": "wörtlich", "text": "\"eine heikle Zezen\""}, {"kategorie": "", "text": "\"ein larmoyantes Zimperlieschen\""}, {"kategorie": "", "text": "\"ein dünnhäutiges Sensibelchen\""}, {"kategorie": "", "text": "\"ein zartbesaitetes Mimöschen\""}]'::jsonb, ''),
  ('a-so-a-haagliche-zaeaezn-is-ma-no-nii-untakumman', 'A so a haagliche Zääzn is ma no nii untakumman!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Eine so eine Zäzen ist mir noch nie untergekommen!', '[{"kategorie": "wörtlich", "text": "\"Ein derart dünnhäutiges Zimperlieschen ist mir noch nie untergekommen!\"  2. Ein derart mimosenhaftes Wesen ist mir noch nie begegnet!  3. Ich hab noch nie jemanden getroffen, der so larmoyant war!"}]'::jsonb, 'a haagliche Zääzn'),
  ('dea-beidlhuutscha-wiafd-schdaendich-sei-aungl-aus-nua-leida-beissd-kaane-au', 'Dea Beidlhuutscha wiafd schdändich sei Aungl aus - nua leida beissd kaane au!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Dieser Beidlhutscher wift ständig seine Angel aus - nur leider beißt keine an!', '[{"kategorie": "wörtlich", "text": "\"Dieser Pimmelschaukler wift ständig seine Angel aus - nur leider beißt keine an!\"  2. Dieser onanierende Aufreiß-Held wirft ständig seine Angel aus – nur leider beißt nie was an!  3. Dieser wichsende Möchtegern-Casanova wirft eine Angel nach der anderen aus – aber im Becken schwimmt halt nichts, das auf ihn wartet!"}]'::jsonb, ''),
  ('du-oodiads-baanagschdoeoe', 'Du oodiads Baanagschdöö!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du abgedörrtes Knochengerüst!', '[{"kategorie": "wörtlich", "text": "\"Du ausgedörrte Skelettfigur!\"  2. \"Du rostiges Gerippe aus der Rumpelkammer!\"  3. Du wandelnder Kleiderbügel auf zwei Beinen!"}]'::jsonb, ''),
  ('an-fuachnscheissa-eakennsd-daraun-dass-a-beim-dreekreiz-glaubd-de-schdodt-wueuer-eam-in-oasch-messn', 'An Fuachnscheissa eakennsd daraun, dass a beim Dreekreiz glaubd, de Schdodt wüür eam in Oasch messn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Einen Furchenscheißer erkennst du daran, dass er beim Drehkreuz glaubt, die Stadt wolle ihm den Arsch messen!', '[{"kategorie": "wörtlich", "text": "\"Einen Bauerntölpel vom Land erkennst du daran, dass er beim Drehkreuz glaubt, die Stadt wolle ihm den Hintern messen!\"  2. Einen echten Hintertupfinger erkennst du daran, dass er beim Drehkreuz meint, die Stadt wolle ihm den Hintern scannen!  3. So einen Provinzhelden erkennst du blitzschnell: der denkt beim Drehkreuz, die Stadt will ihm den Allerwertesten vermessen!"}]'::jsonb, ''),
  ('giigal-sei-des-is-fein-giigal-kaunn-ned-jeeda-sei', 'Giigal sei, des is fein - Giigal kaunn ned jeeda sei!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Gigerl sein, das ist fein, Gigerl kann nicht jeder sein!', '[{"kategorie": "wörtlich", "text": "\"Dandy sein, das ist fein, Dandy kann nicht jeder sein!\"  2. Dandy sein ist wunderbar,\ndoch Dandy wird nicht jeder, klar!  3. Geck zu sein, das ist fein, Geck kann nicht ein jeder sein!"}]'::jsonb, ''),
  ('gschbitzde-schuach-braada-huat-des-schdeed-einem-giigal-guad', 'Gschbitzde Schuach, braada Huat - des schdeed einem Giigal guad!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Gespitzte Schuh und breiter Hut - das steht einem Gigerl gut!', '[{"kategorie": "wörtlich, Reim", "text": "\"Spitze Schuh, schneidiger Hut – dem Gigerl steht das richtig gut!\"  2. Spitze Schuh und Dandy-Hut – dem Geck steht so was richtig gut!  3. Gespitzte Schuh und Federhut – da läuft ein Dandy doppelt gut!"}]'::jsonb, ''),
  ('amoi-da-giigl-amoi-da-googl', 'Amoi da Giigl, amoi da Googl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Einmal der Gigl, einmal der Gogl', '[{"kategorie": "wörtlich", "text": "\"Einmal der Gickel und einmal der Gockel!\"  2. (fig., scherzhaft für):  \"Einmal dieser, einmal jener!\"  3. \"Wen''s trifft, den trifft''s!\"  4. \"Mal so, mal so!\""}]'::jsonb, ''),
  ('waunn-i-zspaet-haamkumm-hod-mi-mei-oide-wiida-bei-d-googaln', 'Waunn I zspät haamkumm, hod mi mei Oide wiida bei d''Googaln!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn ich zu spät nach Hause komme, hat mich meine Alte wieder bei den Gogerln!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich zu spät nach Hause komme, hat mich meine Alte wieder bei den Eiern!\"  2. (fig.) Wenn ich mich verspäte, hat mich meine Alte wieder am Sack!  3. Bin ich nicht pünktlich zu Hause, nimmt mich meine Alte wieder in die Mangel!"}]'::jsonb, ''),
  ('wem-bei-d-googaln-haum', 'wem bei d''Googaln haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden bei den Gogerln haben', '[{"kategorie": "wörtlich", "text": "\"jemanden an den Eiern haben\""}, {"kategorie": "", "text": "\"jemanden am Sack haben\""}, {"kategorie": "", "text": "jemanden am Haken haben\""}, {"kategorie": "", "text": "jemandem in seiner Gewalt haben\""}]'::jsonb, 'De Kiiwara haum eam bei de Googaln - dea kaunn goa nix mea tuan!'),
  ('de-kiiwara-haum-eam-bei-de-googaln-dea-kaunn-goa-nix-mea-tuan', 'De Kiiwara haum eam bei de Googaln - dea kaunn goa nix mea tuan!', '', '', '', 'Wiener Gaunersprache', 'Die Kieberer haben ihn bei den Gogerln, der kann gar nichts mehr tun!', '[{"kategorie": "wörtlich", "text": "\"Die Bullen haben ihn voll an den Eiern, der kann gar nichts mehr machen!\"  2. Die Cops haben ihn am Sack – der kann da gar nichts mehr tun!  3. Der ist sowas von am Haken – der kann nur noch nicken!"}]'::jsonb, ''),
  ('in-gaagl-oda-gaaglschdrauch-haums-im-mittloita-zum-wiazn-von-bia-vawendt', 'In Gaagl oda Gaaglschdrauch haums im Mittloita zum Wiazn von Bia vawendt!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Den Gagel oder Gagelstrauch haben sie im Mittelalter zum Würzen von Bier verwendet!', '[{"kategorie": "wörtlich", "text": "\"In der mittelalterlichen Braukunst war der Gagelstrauch ein verbreitetes Würzkraut für Bier!\"  2. Brauereien des Mittelalters setzten Gagel regelmäßig als Bitter- und Aromawürzstoff ein!  3. Gagel gehörte im Mittelalter zum Standard der Bierkräuter!"}]'::jsonb, '')
